@@ -0,0 +1,169 @@
+<script lang="ts">
+	import { untrack } from 'svelte';
+	import { laporanAtribusiDariBE } from '$lib/adapter/affiliate';
+	import { BULAN_AWAL } from '$lib/affiliate/konfigurasi';
+	import { daftarBulan, geserBulan, labelPeriode } from '$lib/affiliate/periode';
+	import type { MetrikAtribusi } from '$lib/affiliate/tipe';
+	import type { DipostingAtribusiBE } from '$lib/api/tipe';
+	import { contohAtribusi } from '$lib/data/atribusi-affiliate';
+	import { angka, rupiah } from '$lib/format';
+	import { atribusiBanding, type OpsiAtribusi } from '$lib/state/affiliate.svelte';
+	import { menungguData } from '$lib/state/sumber.svelte';
+	import KartuKeadaan from '$lib/ui/pelanggan/KartuKeadaan.svelte';
+	import UbinKpi from '$lib/ui/pelanggan/UbinKpi.svelte';
+
+	/**
+	 * Banding ringkasan periode terpilih dengan periode sebelumnya yang sama
+	 * panjangnya — permintaan sendiri ke `/partners/attribution`, dimuat ulang
+	 * setiap kali filter tanggal berubah.
+	 *
+	 * Periode sebelumnya yang jatuh di luar jangkauan data tidak dipotong jadi
+	 * periode lebih pendek: membandingkan 6 bulan dengan 2 bulan terbaca seperti
+	 * penurunan, padahal yang terjadi hanya datanya belum ada.
+	 */
+
+	interface Props {
+		brand: string;
+		/** 'YYYY-MM' — periode yang sedang ditampilkan halaman. */
+		dari: string;
+		sampai: string;
+		diposting: DipostingAtribusiBE;
+		sekarang: MetrikAtribusi;
+		liveApi: boolean;
+	}
+
+	let { brand, dari, sampai, diposting, sekarang, liveApi }: Props = $props();
+
+	const jumlahBulan = $derived(daftarBulan(dari, sampai).length);
+	const sebelum = $derived.by(() => {
+		const mulai = geserBulan(dari, -jumlahBulan);
+		if (mulai < BULAN_AWAL) return null;
+		return { dari: mulai, sampai: geserBulan(dari, -1) };
+	});
+
+	const opsi = $derived.by<OpsiAtribusi | null>(() =>
+		sebelum
+			? {
+					brand,
+					dari: sebelum.dari,
+					sampai: sebelum.sampai,
+					dim: 'pic',
+					urut: 'gmv',
+					arah: 'desc',
+					/* Hanya ringkasannya yang dipakai; baris rincian sudah ada di tabel halaman. */
+					batas: 1,
+					geser: 0,
+					diposting
+				}
+			: null
+	);
+
+	/* `opsi` dibaca di luar untrack supaya effect ini berlangganan ke seluruh
+	   filter — termasuk tanggal. untrack hanya menutupi panggilannya, sebab
+	   muat() membaca flag `memuat` secara sinkron dan effect yang ikut
+	   berlangganan ke flag itu memanggil dirinya sendiri tanpa henti. */
+	$effect(() => {
+		const opsiMuat = opsi;
+		if (!liveApi || !opsiMuat) return;
+		untrack(() => void atribusiBanding.muat(opsiMuat));
+	});
+
+	const laporan = $derived.by(() => {
+		if (!opsi) return null;
+		if (!liveApi) return laporanAtribusiDariBE(contohAtribusi(opsi));
+		return atribusiBanding.mentah ? laporanAtribusiDariBE(atribusiBanding.mentah) : null;
+	});
+	/* Jawaban periode sebelumnya tidak boleh tampil di bawah label periode yang
+	   baru: selama tanggalnya belum cocok, panel ini masih menunggu — bukan
+	   kosong. Tanpa pemisahan itu, jeda antar-permintaan terbaca "tidak ada
+	   pembanding" padahal datanya sedang jalan. */
+	const cocok = $derived(
+		!!laporan && !!sebelum && laporan.dari === sebelum.dari && laporan.sampai === sebelum.sampai
+	);
+	const laporanCocok = $derived(cocok ? laporan : null);
+	const memuat = $derived(liveApi && atribusiBanding.memuat);
+	const galat = $derived(liveApi ? atribusiBanding.galat : '');
+
+	function delta(kini: number, lalu: number): number | null {
+		if (!lalu) return null;
+		return ((kini - lalu) / lalu) * 100;
+	}
+
+	/* Nilai besar = periode yang dipilih, delta = selisihnya terhadap periode
+	   sebelumnya, meta = angka pembandingnya. Urutan itu yang dibaca BadgeDelta
+	   ("vs lalu"); menaruh angka lama sebagai nilai besar membuat tandanya
+	   terbaca terbalik. */
+	const METRIK = [
+		{ label: 'GMV', ambil: (m: MetrikAtribusi) => m.gmv, format: rupiah },
+		{ label: 'Views', ambil: (m: MetrikAtribusi) => m.views, format: angka },
+		{ label: 'Produk Dilihat', ambil: (m: MetrikAtribusi) => m.produkDilihat, format: angka }
+	] as const;
+
+	const ubin = $derived(
+		laporanCocok && sebelum
+			? METRIK.map(({ label, ambil, format }) => {
+					const lalu = ambil(laporanCocok.ringkasan);
+					return {
+						label,
+						nilai: format(ambil(sekarang)),
+						d: delta(ambil(sekarang), lalu),
+						meta: `${labelPeriode(sebelum.dari, sebelum.sampai)}: ${format(lalu)}`
+					};
+				})
+			: []
+	);
+</script>
+
+<section
+	class="rounded-[14px] border border-line bg-surface p-4"
+	aria-labelledby="judul-banding"
+	data-uji="banding"
+>
+	<div class="flex flex-wrap items-start justify-between gap-3">
+		<div>
+			<h3 id="judul-banding" class="text-[14px] font-semibold text-ink">Dibanding periode sebelumnya</h3>
+			<p class="mt-0.5 text-[12px] text-muted">
+				{#if sebelum}
+					Pembandingnya {labelPeriode(sebelum.dari, sebelum.sampai)} — {jumlahBulan}
+					bulan tepat sebelum periode yang dipilih.{#if memuat}<span role="status"> Memuat…</span>{/if}
+				{:else}
+					Periode sebanding sebelum {labelPeriode(dari, sampai)} jatuh sebelum Jan 2024.
+				{/if}
+			</p>
+		</div>
+	</div>
+
+	{#if !sebelum}
+		<p class="mt-3 rounded-lg border border-line bg-raised px-3 py-2 text-[12.5px] text-muted" data-uji="banding-luar-jangkauan">
+			Video affiliate tercatat sejak Jan 2024, jadi tidak ada {jumlahBulan} bulan sebelum periode ini untuk
+			dibandingkan. Pilih periode yang lebih baru atau lebih pendek.
+		</p>
+	{:else if !laporanCocok}
+		<div class="mt-3" data-uji={galat ? 'banding-galat' : 'banding-memuat'}>
+			<KartuKeadaan
+				memuat={menungguData(liveApi, laporanCocok, galat)}
+				{galat}
+				ulang={() => atribusiBanding.ulang()}
+				judul="banding periode sebelumnya"
+				sumber="partners/attribution"
+				tinggi="9rem"
+			/>
+		</div>
+	{:else if !laporanCocok.ada}
+		<p class="mt-3 rounded-lg border border-dashed border-line bg-raised px-3 py-2 text-[12.5px] text-muted" data-uji="banding-kosong">
+			Belum ada data atribusi {brand} untuk {labelPeriode(sebelum.dari, sebelum.sampai)}, jadi tidak ada
+			pembanding.
+		</p>
+	{:else}
+		<div
+			class="mt-3 grid gap-4 sm:grid-cols-3"
+			aria-label="Banding dengan periode sebelumnya"
+			aria-busy={memuat}
+			class:opacity-70={memuat}
+		>
+			{#each ubin as u (u.label)}
+				<UbinKpi label={u.label} nilai={u.nilai} delta={u.d} satuanDelta="%" meta={u.meta} />
+			{/each}
+		</div>
+	{/if}
+</section>
