diff --git a/backend/internal/domain/gift_card.go b/backend/internal/domain/gift_card.go
new file mode 100644
index 00000000..fbdf7d82
--- /dev/null
+++ b/backend/internal/domain/gift_card.go
@@ -0,0 +1,21 @@
+package domain
+
+import "time"
+
+// GiftCard is the stored balance a card carries, not its movement history: the
+// ledger rows belong to whoever writes the debit. It lives here rather than in
+// service because the repository returning it cannot import service.
+type GiftCard struct {
+	ID        string
+	Code      string
+	Balance   int64
+	ExpiresAt *time.Time
+	IsActive  bool
+}
+
+// Expired reads ExpiresAt as the instant validity ENDS, half-open like every
+// other range owner here, so a card is already dead at its own expiry stamp. A
+// nil stamp is a card that never expires, not one that expired at the zero time.
+func (g GiftCard) Expired(at time.Time) bool {
+	return g.ExpiresAt != nil && !at.Before(*g.ExpiresAt)
+}
diff --git a/backend/internal/service/gift_card_service.go b/backend/internal/service/gift_card_service.go
new file mode 100644
index 00000000..bd40c28f
--- /dev/null
+++ b/backend/internal/service/gift_card_service.go
@@ -0,0 +1,87 @@
+package service
+
+import (
+	"context"
+	"errors"
+	"strings"
+	"time"
+
+	"github.com/kitapos/kitapos/internal/domain"
+	"github.com/kitapos/kitapos/internal/repository"
+)
+
+// These four reach the cashier's screen verbatim once the handler forwards
+// err.Error() through writeError, so they are copy, not log text.
+var (
+	ErrGiftCardUnknown       = errors.New("kode kartu hadiah tidak dikenali")
+	ErrGiftCardInactive      = errors.New("kartu hadiah sudah tidak aktif")
+	ErrGiftCardExpired       = errors.New("kartu hadiah sudah kedaluwarsa")
+	ErrGiftCardInsufficient  = errors.New("saldo kartu hadiah tidak cukup")
+	ErrGiftCardAmountInvalid = errors.New("nominal penukaran harus lebih dari nol")
+)
+
+// giftCardRepository is the slice of the coming repository this service needs.
+type giftCardRepository interface {
+	FindByCode(ctx context.Context, code string) (*domain.GiftCard, error)
+	// Debit carries the balance guard INSIDE its UPDATE statement
+	// (WHERE balance >= amount AND is_active), so two cashiers redeeming the
+	// same card at once cannot both pass it. ok=false is that guard refusing,
+	// which is a business answer and not an error.
+	Debit(ctx context.Context, cardID string, amount int64) (ok bool, err error)
+}
+
+type GiftCardService struct {
+	repo giftCardRepository
+	now  func() time.Time
+}
+
+func NewGiftCardService(repo giftCardRepository) *GiftCardService {
+	return &GiftCardService{repo: repo, now: time.Now}
+}
+
+// Redeem spends amount off the card named by code. The read-then-debit pair
+// exists for the MESSAGE, not for the decision: the checks below tell the cashier
+// which of the four refusals happened, while the one that actually protects the
+// balance is the guard inside repo.Debit. Reading first and trusting the read
+// would let two concurrent redemptions overdraw the card.
+func (s *GiftCardService) Redeem(ctx context.Context, code string, amount int64) error {
+	if amount <= 0 {
+		return ErrGiftCardAmountInvalid
+	}
+	if err := domain.ValidateBillAmount(amount); err != nil {
+		return err
+	}
+	code = strings.TrimSpace(code)
+	if code == "" {
+		return ErrGiftCardUnknown
+	}
+
+	card, err := s.repo.FindByCode(ctx, code)
+	if errors.Is(err, repository.ErrNotFound) {
+		return ErrGiftCardUnknown
+	}
+	if err != nil {
+		return err
+	}
+	if card == nil {
+		return ErrGiftCardUnknown
+	}
+	if !card.IsActive {
+		return ErrGiftCardInactive
+	}
+	if card.Expired(s.now()) {
+		return ErrGiftCardExpired
+	}
+	if card.Balance < amount {
+		return ErrGiftCardInsufficient
+	}
+
+	ok, err := s.repo.Debit(ctx, card.ID, amount)
+	if err != nil {
+		return err
+	}
+	if !ok {
+		return ErrGiftCardInsufficient
+	}
+	return nil
+}
