+
+type stubGiftCardRepo struct {
+	card      *domain.GiftCard
+	findErr   error
+	debitOK   bool
+	debitErr  error
+	debited   int64
+	debitCall int
+}
+
+func (s *stubGiftCardRepo) FindByCode(ctx context.Context, code string) (*domain.GiftCard, error) {
+	if s.findErr != nil {
+		return nil, s.findErr
+	}
+	return s.card, nil
+}
+
+func (s *stubGiftCardRepo) Debit(ctx context.Context, cardID string, amount int64) (bool, error) {
+	s.debitCall++
+	s.debited = amount
+	return s.debitOK, s.debitErr
+}
+
+func giftCard(balance int64, expiresAt *time.Time) *domain.GiftCard {
+	return &domain.GiftCard{ID: "0199a1f0-5a3e-7c21-9d44-4f1b2c3d4e5f", Code: "KADO-4821-7Q", Balance: balance, ExpiresAt: expiresAt, IsActive: true}
+}
+
+func at(d time.Duration) *time.Time {
+	t := time.Now().Add(d)
+	return &t
+}
+
+func TestGiftCardRedeem(t *testing.T) {
+	cases := []struct {
+		name   string
+		repo   *stubGiftCardRepo
+		amount int64
+		want   error
+		debits bool
+	}{
+		{"saldo cukup", &stubGiftCardRepo{card: giftCard(150000, at(720*time.Hour)), debitOK: true}, 45000, nil, true},
+		{"tanpa kedaluwarsa", &stubGiftCardRepo{card: giftCard(45000, nil), debitOK: true}, 45000, nil, true},
+		{"saldo kurang", &stubGiftCardRepo{card: giftCard(30000, nil)}, 45000, service.ErrGiftCardInsufficient, false},
+		{"kedaluwarsa", &stubGiftCardRepo{card: giftCard(150000, at(-1*time.Hour))}, 45000, service.ErrGiftCardExpired, false},
+		{"kode asing", &stubGiftCardRepo{findErr: repository.ErrNotFound}, 45000, service.ErrGiftCardUnknown, false},
+		{"kode kosong", &stubGiftCardRepo{card: giftCard(150000, nil)}, 45000, service.ErrGiftCardUnknown, false},
+		{"nominal nol", &stubGiftCardRepo{card: giftCard(150000, nil)}, 0, service.ErrGiftCardAmountInvalid, false},
+		{"nominal negatif", &stubGiftCardRepo{card: giftCard(150000, nil)}, -45000, service.ErrGiftCardAmountInvalid, false},
+		{"kalah balapan", &stubGiftCardRepo{card: giftCard(150000, nil), debitOK: false}, 45000, service.ErrGiftCardInsufficient, true},
+	}
+	for _, c := range cases {
+		t.Run(c.name, func(t *testing.T) {
+			code := "KADO-4821-7Q"
+			if c.name == "kode kosong" {
+				code = "   "
+			}
+			err := service.NewGiftCardService(c.repo).Redeem(context.Background(), code, c.amount)
+			if !errors.Is(err, c.want) {
+				t.Fatalf("Redeem err = %v, want %v", err, c.want)
+			}
+			if c.debits && c.repo.debitCall != 1 {
+				t.Fatalf("debit calls = %d, want 1", c.repo.debitCall)
+			}
+			if !c.debits && c.repo.debitCall != 0 {
+				t.Fatalf("debit calls = %d, want 0 (refusal must not touch the balance)", c.repo.debitCall)
+			}
+			if c.debits && c.repo.debited != c.amount {
+				t.Fatalf("debited %d, want %d", c.repo.debited, c.amount)
+			}
+		})
+	}
+}
+
+func TestGiftCardRedeemInactive(t *testing.T) {
+	card := giftCard(150000, nil)
+	card.IsActive = false
+	repo := &stubGiftCardRepo{card: card}
+	err := service.NewGiftCardService(repo).Redeem(context.Background(), "KADO-4821-7Q", 45000)
+	if !errors.Is(err, service.ErrGiftCardInactive) {
+		t.Fatalf("Redeem err = %v, want ErrGiftCardInactive", err)
+	}
+	if repo.debitCall != 0 {
+		t.Fatalf("debit calls = %d, want 0", repo.debitCall)
+	}
+}

