+import { describe, expect, it } from 'vitest';
+import { deltaPersen, periodeSebelum } from './pembanding';
+
+describe('periodeSebelum', () => {
+	it('mengambil jendela sepanjang periode utama, tepat sebelumnya', () => {
+		expect(periodeSebelum('2026-05', '2026-10')).toEqual({
+			dari: '2025-11',
+			sampai: '2026-04',
+			bulan: 6,
+			penuh: true
+		});
+	});
+
+	it('satu bulan dibandingkan dengan satu bulan', () => {
+		expect(periodeSebelum('2026-10', '2026-10')).toEqual({
+			dari: '2026-09',
+			sampai: '2026-09',
+			bulan: 1,
+			penuh: true
+		});
+	});
+
+	it('memotong di Jan 2024 dan menandai jendelanya tidak penuh', () => {
+		expect(periodeSebelum('2024-03', '2024-08')).toEqual({
+			dari: '2024-01',
+			sampai: '2024-02',
+			bulan: 2,
+			penuh: false
+		});
+	});
+
+	it('tidak ada pembanding untuk periode yang mulai di bulan pertama data', () => {
+		expect(periodeSebelum('2024-01', '2024-06')).toBeNull();
+	});
+});
+
+describe('deltaPersen', () => {
+	it('menghitung naik dan turun', () => {
+		expect(deltaPersen(150, 100)).toBeCloseTo(50);
+		expect(deltaPersen(80, 100)).toBeCloseTo(-20);
+	});
+
+	it.each([0, -1, Number.NaN])('pembanding %s tidak punya persentase', (lalu) => {
+		expect(deltaPersen(100, lalu)).toBeNull();
+	});
+});
