+/**
+ * Jendela pembanding: satu periode bulan penuh persis sebelum periode yang dipilih.
+ *
+ * Kedua sisi perbandingan dipaku ke bulan eksplisit, bukan dihitung ulang dari
+ * "6 bulan terakhir" di sisi pembanding — kalau tidak, dua sisi yang dibandingkan
+ * bisa berangkat dari jam yang berbeda dan selisihnya jadi tidak berarti.
+ */
+import { BULAN_AWAL } from './konfigurasi';
+import { daftarBulan, geserBulan } from './periode';
+
+export interface PeriodePembanding {
+	/** 'YYYY-MM' */
+	dari: string;
+	sampai: string;
+	/** Jumlah bulan yang benar-benar dibandingkan. */
+	bulan: number;
+	/** False bila jendelanya dipotong BULAN_AWAL, jadi lebih pendek dari periode utama. */
+	penuh: boolean;
+}
+
+/** Null bila tidak ada bulan sebelum periode ini yang punya data. */
+export function periodeSebelum(dari: string, sampai: string): PeriodePembanding | null {
+	const panjang = daftarBulan(dari, sampai).length;
+	if (!panjang) return null;
+
+	const sampaiLalu = geserBulan(dari, -1);
+	if (sampaiLalu < BULAN_AWAL) return null;
+
+	const dariLalu = geserBulan(dari, -panjang);
+	const dipotong = dariLalu < BULAN_AWAL;
+	const awal = dipotong ? BULAN_AWAL : dariLalu;
+
+	return {
+		dari: awal,
+		sampai: sampaiLalu,
+		bulan: daftarBulan(awal, sampaiLalu).length,
+		penuh: !dipotong
+	};
+}
+
+/** Perubahan relatif dalam persen. Null bila pembandingnya nol: tumbuh dari nol tidak punya angka. */
+export function deltaPersen(sekarang: number, lalu: number): number | null {
+	if (!Number.isFinite(sekarang) || !Number.isFinite(lalu) || lalu <= 0) return null;
+
+	return ((sekarang - lalu) / lalu) * 100;
+}
