+<script lang="ts">
+	import { untrack } from 'svelte';
+	import { laporanAtribusiDariBE } from '$lib/adapter/affiliate';
+	import { deltaPersen, periodeSebelum } from '$lib/affiliate/pembanding';
+	import { labelPeriode } from '$lib/affiliate/periode';
+	import { METRIK_GRAFIK, type MetrikGrafik } from '$lib/affiliate/konfigurasi';
+	import type { MetrikAtribusi } from '$lib/affiliate/tipe';
+	import type { DipostingAtribusiBE } from '$lib/api/tipe';
+	import { contohAtribusi } from '$lib/data/atribusi-affiliate';
+	import { angka, rupiah } from '$lib/format';
+	import { atribusiBanding, type OpsiAtribusi } from '$lib/state/affiliate.svelte';
+	import KartuKeadaan from '$lib/ui/pelanggan/KartuKeadaan.svelte';
+	import UbinKpi from '$lib/ui/pelanggan/UbinKpi.svelte';
+
+	/**
+	 * Ringkasan periode terpilih dibandingkan jendela bulan penuh persis sebelumnya.
+	 *
+	 * Angka pembandingnya permintaan sendiri ke `/partners/attribution`, bukan potongan
+	 * dari jawaban halaman — jawaban halaman hanya membawa bulan di dalam periode, jadi
+	 * bulan sebelumnya tidak ada di sana. Permintaannya minta `limit: 1` karena yang
+	 * dipakai hanya `summary`; rincian barisnya dibuang.
+	 */
+	interface Props {
+		brand: string;
+		/** 'YYYY-MM' — periode yang sedang dilihat halaman. */
+		dari: string;
+		sampai: string;
+		diposting: DipostingAtribusiBE;
+		sekarang: MetrikAtribusi;
+		liveApi: boolean;
+	}
+
+	let { brand, dari, sampai, diposting, sekarang, liveApi }: Props = $props();
+
+	const lalu = $derived(periodeSebelum(dari, sampai));
+
+	const opsi = $derived.by<OpsiAtribusi | null>(() =>
+		lalu
+			? {
+					brand,
+					dari: lalu.dari,
+					sampai: lalu.sampai,
+					dim: 'pic',
+					urut: 'gmv',
+					arah: 'desc',
+					batas: 1,
+					geser: 0,
+					diposting
+				}
+			: null
+	);
+
+	/* Argumen dibaca di luar untrack supaya setiap perubahan filter tanggal (dan brand,
+	   dan mode video) memuat ulang pembandingnya; panggilannya di dalam untrack supaya
+	   `memuat`/`galat` yang dibaca muat() sendiri tidak jadi dependensi — itu yang dulu
+	   membuat effect memanggil loader berulang kali saat BE menjawab galat. */
+	$effect(() => {
+		if (!liveApi) return;
+		const o = opsi;
+		if (!o) return;
+		untrack(() => void atribusiBanding.muat(o));
+	});
+
+	const laporan = $derived(
+		!opsi ? null : liveApi ? (atribusiBanding.mentah ? laporanAtribusiDariBE(atribusiBanding.mentah) : null) : laporanAtribusiDariBE(contohAtribusi(opsi))
+	);
+	/* Jawaban yang tertinggal dari rentang sebelumnya tidak boleh tampil di bawah label rentang yang baru. */
+	const cocok = $derived(
+		!!laporan && !!lalu && laporan.dari === lalu.dari && laporan.sampai === lalu.sampai
+	);
+	const galat = $derived(liveApi ? atribusiBanding.galat : '');
+	/* Galat mematikan keadaan memuat: `cocok` tetap false setelah permintaan gagal
+	   (tidak ada payload), jadi tanpa ini kartu galat tertutup skeleton selamanya. */
+	const memuat = $derived(liveApi && !galat && (atribusiBanding.memuat || !cocok));
+	const pembanding = $derived(cocok && laporan?.ada ? laporan.ringkasan : null);
+
+	const UBIN: { kunci: MetrikGrafik; format: (n: number) => string; info?: string }[] = [
+		{ kunci: 'gmv', format: rupiah },
+		{ kunci: 'views', format: angka },
+		{
+			kunci: 'produkDilihat',
+			format: angka,
+			info: 'Berapa kali kartu produk di video dilihat penonton.'
+		}
+	];
+	const ubin = $derived(
+		UBIN.map((u) => ({
+			...u,
+			label: METRIK_GRAFIK.find((m) => m.kunci === u.kunci)?.label ?? u.kunci,
+			nilai: sekarang[u.kunci],
+			lalu: pembanding ? pembanding[u.kunci] : null
+		}))
+	);
+</script>
+
+<section
+	class="mt-4 rounded-[14px] border border-line bg-surface p-4"
+	aria-labelledby="judul-banding"
+	data-uji="banding-periode"
+>
+	<div class="flex flex-wrap items-start justify-between gap-3">
+		<div>
+			<h3 id="judul-banding" class="text-[14px] font-semibold text-ink">Dibanding periode sebelumnya</h3>
+			<p class="mt-0.5 text-[12px] text-muted">
+				{labelPeriode(dari, sampai)}
+				{#if lalu}
+					vs <span data-uji="banding-rentang">{labelPeriode(lalu.dari, lalu.sampai)}</span>
+				{/if}
+				{#if memuat && lalu}<span role="status" data-uji="banding-memuat"> · memuat pembanding…</span>{/if}
+			</p>
+		</div>
+	</div>
+
+	{#if !lalu}
+		<p class="mt-3 rounded-lg border border-line bg-raised px-3 py-2 text-[12.5px] text-muted" data-uji="banding-tanpa">
+			Tidak ada pembanding: periode ini sudah mulai di bulan pertama yang punya data video affiliate
+			(Jan 2024). Pilih periode yang mulai lebih belakangan untuk melihat selisihnya.
+		</p>
+	{:else if !pembanding}
+		<div class="mt-3" data-uji={galat ? 'banding-galat' : 'banding-keadaan'}>
+			<KartuKeadaan
+				{memuat}
+				kosong={!memuat && !galat}
+				{galat}
+				ulang={() => atribusiBanding.ulang()}
+				judul="pembanding {labelPeriode(lalu.dari, lalu.sampai)}"
+				sumber="partners/attribution"
+				tinggi="8rem"
+			/>
+		</div>
+	{:else}
+		{#if !lalu.penuh}
+			<p class="mt-3 rounded-lg border border-warning/40 bg-warning-soft px-3 py-2 text-[12.5px] text-ink" role="note" data-uji="banding-pendek">
+				Pembandingnya hanya {lalu.bulan} bulan — data video affiliate baru dimulai Jan 2024, jadi
+				jendela sebelum periode ini lebih pendek dan selisihnya tidak sebanding bulan-per-bulan.
+			</p>
+		{/if}
+		<div class="mt-3 grid gap-4 sm:grid-cols-3" aria-label="Selisih terhadap periode sebelumnya">
+			{#each ubin as u (u.kunci)}
+				<UbinKpi
+					label={u.label}
+					nilai={u.format(u.nilai)}
+					delta={u.lalu === null ? null : deltaPersen(u.nilai, u.lalu)}
+					satuanDelta="%"
+					info={u.info}
+					meta={u.lalu === null
+						? undefined
+						: u.lalu > 0
+							? `${labelPeriode(lalu.dari, lalu.sampai)}: ${u.format(u.lalu)}`
+							: `${labelPeriode(lalu.dari, lalu.sampai)}: ${u.format(u.lalu)} — tidak ada selisih yang bisa dihitung dari nol`}
+				/>
+			{/each}
+		</div>
+	{/if}
+</section>
