+
+/** Rentang sepanjang `dari..sampai` tepat sebelum `dari`.
+ *
+ *  `ada` false bila salah satu ujungnya bukan 'YYYY-MM' atau rentangnya jatuh
+ *  sebelum `batasAwal`: membandingkan 6 bulan dengan 3 bulan pertama yang
+ *  tercatat terbaca sebagai penurunan yang tidak pernah terjadi. */
+export function jendelaSebelumnya(
+	dari: string,
+	sampai: string,
+	batasAwal: string
+): { panjang: number; dari: string; sampai: string; ada: boolean; sebelumAwal: boolean } {
+	const awalKini = kunciBulan(dari);
+	const akhirKini = kunciBulan(sampai);
+	if (!awalKini || !akhirKini) return { panjang: 0, dari: '', sampai: '', ada: false, sebelumAwal: false };
+
+	const panjang = daftarBulan(awalKini, akhirKini).length;
+	const awal = geserBulan(awalKini, -panjang);
+	const ada = awal >= batasAwal;
+
+	return { panjang, dari: awal, sampai: geserBulan(awalKini, -1), ada, sebelumAwal: !ada };
+}
