+import { readFileSync, readdirSync } from 'node:fs';
+import { join } from 'node:path';
+import { describe, expect, it } from 'vitest';
+
+/**
+ * Gerbang satu kelas cacat: `$effect` yang memanggil `muat(...)` dengan nilai
+ * turunan yang dibaca DI DALAM `untrack` tidak punya dependensi apa pun, jadi
+ * mengubah filter tidak memuat ulang apa-apa — dan tidak ada yang error.
+ *
+ * Bentuk yang benar (dipakai di seluruh repo): nilai dibaca ke `const` di dalam
+ * badan `$effect`, lalu `const` itu yang masuk ke `untrack`.
+ */
+const AKAR = 'src';
+
+/* Cacat yang sudah ada sebelum gerbang ini, di halaman lain: filter dan paginasinya
+   tidak memuat ulang. Dicatat di sini supaya gerbangnya hijau sekarang dan tetap
+   menangkap yang BERIKUTNYA — bukan supaya ketiganya dianggap benar. */
+const DIKETAHUI = [
+	'src/lib/ui/crm/LaciCrm.svelte: muatDaftar(filter)',
+	'src/lib/ui/pelanggan/HalamanReview.svelte: muatRingkasan(filter)',
+	'src/lib/ui/pelanggan/HalamanReview.svelte: muatDaftar(filter)'
+];
+
+function berkasSumber(dir: string): string[] {
+	return readdirSync(dir, { withFileTypes: true }).flatMap((e) => {
+		const jalur = join(dir, e.name);
+		if (e.isDirectory()) return berkasSumber(jalur);
+		return /\.(svelte|ts)$/.test(e.name) ? [jalur] : [];
+	});
+}
+
+/** Badan setiap `$effect(() => { ... })` di satu berkas, dengan kurung berimbang. */
+function badanEffect(teks: string): string[] {
+	const hasil: string[] = [];
+	const pola = /\$effect\(\s*\(\)\s*=>\s*\{/g;
+	for (let m = pola.exec(teks); m; m = pola.exec(teks)) {
+		let dalam = 1;
+		let i = m.index + m[0].length;
+		const mulai = i;
+		for (; i < teks.length && dalam > 0; i++) {
+			if (teks[i] === '{') dalam++;
+			else if (teks[i] === '}') dalam--;
+		}
+		hasil.push(teks.slice(mulai, i - 1));
+	}
+
+	return hasil;
+}
+
+describe('muat di dalam $effect', () => {
+	const temuan: string[] = [];
+	let diperiksa = 0;
+
+	for (const berkas of berkasSumber(AKAR)) {
+		const teks = readFileSync(berkas, 'utf8');
+		if (!teks.includes('$effect(')) continue;
+		for (const badan of badanEffect(teks)) {
+			const pola = /untrack\(\s*\(\)\s*=>\s*(?:void\s*)?[\w.]*\.(muat\w*)\(\s*([A-Za-z_$][\w$]*)\s*[,)]/g;
+			for (let m = pola.exec(badan); m; m = pola.exec(badan)) {
+				diperiksa++;
+				const arg = m[2];
+				const lokal = new RegExp(`(?:const|let)\\s+${arg}\\b`).test(badan);
+				if (lokal) continue;
+				const tanda = `${berkas}: ${m[1]}(${arg})`;
+				if (!DIKETAHUI.includes(tanda)) temuan.push(`${tanda} — ${arg} tidak dibaca di luar untrack`);
+			}
+		}
+	}
+
+	it('memeriksa setiap pemanggilan muat di dalam untrack', () => {
+		expect(diperiksa).toBeGreaterThan(8);
+	});
+
+	it('setiap nilai yang masuk ke muat dibaca sebagai dependensi $effect', () => {
+		expect(temuan).toEqual([]);
+	});
+});
