+import { describe, expect, it } from 'vitest';
+import { dataContohLeadAkuisisi } from '$lib/data/marketing';
+import {
+	KANAL_AKUISISI,
+	csvLead,
+	perKanalAkuisisi,
+	saringLead,
+	totalLead,
+	type RekapLeadHarian
+} from './marketing';
+
+const baris = (date: string, brand: string, kanal: string, leads: number): RekapLeadHarian => ({
+	date,
+	brand,
+	kanal,
+	leads
+});
+
+describe('saringLead', () => {
+	const rows = [
+		baris('2026-06-01', 'Brighty', 'Meta Ads', 10),
+		baris('2026-06-15', 'Ciara', 'Organik', 20),
+		baris('2026-07-01', 'Brighty', 'Meta Ads', 30)
+	];
+
+	it('memotong di luar rentang tanggal', () => {
+		const hasil = saringLead(rows, { merek: 'ALL', dari: '2026-06-01', sampai: '2026-06-30' });
+		expect(hasil.map((r) => r.leads)).toEqual([10, 20]);
+	});
+
+	it('menyaring per brand dan menerima ALL', () => {
+		const opsi = { dari: '2026-01-01', sampai: '2026-12-31' };
+		expect(saringLead(rows, { ...opsi, merek: 'Brighty' }).map((r) => r.leads)).toEqual([10, 30]);
+		expect(saringLead(rows, { ...opsi, merek: 'ALL' })).toHaveLength(3);
+	});
+
+	it('batas rentang inklusif di kedua ujung', () => {
+		const hasil = saringLead(rows, { merek: 'ALL', dari: '2026-06-01', sampai: '2026-07-01' });
+		expect(hasil).toHaveLength(3);
+	});
+});
+
+describe('perKanalAkuisisi', () => {
+	const biaya = { metaAds: 900_000, tiktokAds: 400_000, shopeeAds: 0, kol: 0, affiliate: 0 };
+
+	it('menjumlahkan lead per channel dan menahan urutan taksonomi', () => {
+		const hasil = perKanalAkuisisi(
+			[
+				baris('2026-06-01', 'Brighty', 'Meta Ads', 60),
+				baris('2026-06-02', 'Ciara', 'Meta Ads', 30),
+				baris('2026-06-01', 'Brighty', 'Organik', 10)
+			],
+			biaya
+		);
+		expect(hasil.map((b) => b.nama)).toEqual(KANAL_AKUISISI.map((k) => k.nama));
+		expect(hasil.find((b) => b.nama === 'Meta Ads')!.leads).toBe(90);
+		expect(hasil.find((b) => b.nama === 'Organik')!.leads).toBe(10);
+	});
+
+	it('porsi dihitung dari total lead dan berjumlah 1', () => {
+		const hasil = perKanalAkuisisi(
+			[
+				baris('2026-06-01', 'Brighty', 'Meta Ads', 75),
+				baris('2026-06-01', 'Brighty', 'Organik', 25)
+			],
+			biaya
+		);
+		expect(hasil.find((b) => b.nama === 'Meta Ads')!.porsi).toBeCloseTo(0.75);
+		expect(hasil.reduce((a, b) => a + b.porsi, 0)).toBeCloseTo(1);
+	});
+
+	it('channel organik membawa cost null, bukan nol', () => {
+		const hasil = perKanalAkuisisi([baris('2026-06-01', 'Brighty', 'Organik', 10)], biaya);
+		const organik = hasil.find((b) => b.nama === 'Organik')!;
+		expect(organik.cost).toBeNull();
+		expect(organik.cpl).toBeNull();
+		expect(organik.berbayar).toBe(false);
+	});
+
+	it('cpl = cost / lead pada channel berbayar', () => {
+		const hasil = perKanalAkuisisi([baris('2026-06-01', 'Brighty', 'Meta Ads', 90)], biaya);
+		expect(hasil.find((b) => b.nama === 'Meta Ads')!.cpl).toBeCloseTo(10_000);
+	});
+
+	it('biaya tanpa lead ditandai, bukan jadi CPL tak hingga', () => {
+		const hasil = perKanalAkuisisi([baris('2026-06-01', 'Brighty', 'Organik', 10)], biaya);
+		const tiktok = hasil.find((b) => b.nama === 'TikTok Ads')!;
+		expect(tiktok.leads).toBe(0);
+		expect(tiktok.cost).toBe(400_000);
+		expect(tiktok.cpl).toBeNull();
+		expect(tiktok.borosTanpaLead).toBe(true);
+		expect(Number.isFinite(tiktok.cpl ?? 0)).toBe(true);
+	});
+
+	it('rentang tanpa satu pun lead tidak melempar dan tidak mengarang porsi', () => {
+		const hasil = perKanalAkuisisi([], biaya);
+		expect(hasil.every((b) => b.leads === 0 && b.porsi === 0 && b.cpl === null)).toBe(true);
+		expect(totalLead(hasil).leads).toBe(0);
+		expect(totalLead(hasil).cpl).toBeNull();
+	});
+
+	it('channel di luar taksonomi tetap tampil dan ditandai, tidak dibuang', () => {
+		const hasil = perKanalAkuisisi([baris('2026-06-01', 'Brighty', 'Marketplace DM', 40)], biaya);
+		const asing = hasil.find((b) => b.nama === 'Marketplace DM');
+		expect(asing).toBeDefined();
+		expect(asing!.leads).toBe(40);
+		expect(asing!.takDikenal).toBe(true);
+		expect(asing!.cost).toBeNull();
+		expect(hasil.filter((b) => b.takDikenal)).toHaveLength(1);
+	});
+
+	it('bucket biaya yang tidak dikirim dibaca nol, tidak NaN', () => {
+		const hasil = perKanalAkuisisi([baris('2026-06-01', 'Brighty', 'KOL / KOC', 5)], {});
+		const kol = hasil.find((b) => b.nama === 'KOL / KOC')!;
+		expect(kol.cost).toBe(0);
+		expect(kol.cpl).toBeNull();
+	});
+});
+
+describe('totalLead', () => {
+	it('menjumlahkan lead dan biaya, cpl dari keduanya', () => {
+		const hasil = perKanalAkuisisi(
+			[
+				baris('2026-06-01', 'Brighty', 'Meta Ads', 60),
+				baris('2026-06-01', 'Brighty', 'Organik', 40)
+			],
+			{ metaAds: 1_000_000, tiktokAds: 0, shopeeAds: 0, kol: 0, affiliate: 0 }
+		);
+		const t = totalLead(hasil);
+		expect(t.leads).toBe(100);
+		expect(t.cost).toBe(1_000_000);
+		expect(t.cpl).toBeCloseTo(10_000);
+	});
+});
+
+describe('dataContohLeadAkuisisi', () => {
+	const rows = dataContohLeadAkuisisi();
+
+	it('hanya memakai channel yang ada di taksonomi', () => {
+		const dikenal = new Set(KANAL_AKUISISI.map((k) => k.nama));
+		expect(rows.every((r) => dikenal.has(r.kanal))).toBe(true);
+	});
+
+	it('memakai tanggal yang sama dengan deret revenue contoh', () => {
+		expect([...new Set(rows.map((r) => r.date))].sort()).toEqual([
+			'2026-05-31',
+			'2026-06-15',
+			'2026-07-15',
+			'2026-08-15',
+			'2026-09-10'
+		]);
+	});
+
+	it('setiap brand punya lead di setiap channel, tidak ada lubang palsu', () => {
+		const hasil = perKanalAkuisisi(rows, {});
+		expect(hasil.every((b) => b.takDikenal || b.leads > 0)).toBe(true);
+	});
+
+	it('volumenya jauh di bawah jumlah order, bukan seluruh pembelian', () => {
+		expect(totalLead(perKanalAkuisisi(rows, {})).leads).toBeLessThan(100_000);
+	});
+});
+
+describe('csvLead', () => {
+	it('membawa BOM, kepala, dan satu baris per channel', () => {
+		const isi = csvLead(perKanalAkuisisi([baris('2026-06-01', 'Brighty', 'Meta Ads', 10)], {}));
+		expect(isi.startsWith('﻿')).toBe(true);
+		const garis = isi.split('\r\n');
+		expect(garis[0]).toContain('Channel akuisisi');
+		expect(garis).toHaveLength(KANAL_AKUISISI.length + 1);
+	});
+
+	it('cost kosong untuk channel organik, bukan 0', () => {
+		const isi = csvLead(perKanalAkuisisi([baris('2026-06-01', 'Brighty', 'Organik', 10)], {}));
+		const organik = isi.split('\r\n').find((l) => l.startsWith('Organik'))!;
+		expect(organik.endsWith(',,')).toBe(true);
+	});
+});
