 }
+
+/* --- Lead per channel akuisisi -------------------------------------------
+   BE Funnel belum punya jumlah lead: tidak ada tabel yang menyimpannya dan
+   tidak ada endpoint yang menjawabnya (`/pipeline` — modul yang memegang
+   leads — menjawab `unavailable`). Jadi agregatnya ditulis di sini sebagai
+   fungsi murni atas baris yang kita pegang sendiri, bukan sebagai bentuk
+   respons di `tipe.ts`: sebuah tipe respons tanpa pemanggil akan terbaca
+   sebagai spesifikasi BE padahal belum pernah dieksekusi, dan bebas salah.
+
+   Lima dari tujuh channel sengaja memakai nama bucket biaya yang sudah ada
+   di halaman ini, supaya cost per lead memakai biaya sungguhan begitu angka
+   lead-nya datang. Dua channel organik tidak punya bucket, dan biayanya
+   `null` — bukan nol, yang akan terbaca sebagai "gratis". */
+
+export interface RekapLeadHarian {
+	date: string;
+	brand: string;
+	kanal: string;
+	leads: number;
+}
+
+export type EmberBiaya = 'metaAds' | 'shopeeAds' | 'tiktokAds' | 'kol' | 'affiliate';
+
+export interface KanalAkuisisi {
+	nama: string;
+	ember: EmberBiaya | null;
+}
+
+export const KANAL_AKUISISI: KanalAkuisisi[] = [
+	{ nama: 'Meta Ads', ember: 'metaAds' },
+	{ nama: 'TikTok Ads', ember: 'tiktokAds' },
+	{ nama: 'Shopee Ads', ember: 'shopeeAds' },
+	{ nama: 'KOL / KOC', ember: 'kol' },
+	{ nama: 'Affiliate', ember: 'affiliate' },
+	{ nama: 'Organik', ember: null },
+	{ nama: 'WhatsApp / CS', ember: null }
+];
+
+export interface BarisLeadKanal {
+	nama: string;
+	berbayar: boolean;
+	leads: number;
+	porsi: number;
+	cost: number | null;
+	cpl: number | null;
+	/** Ada biaya, tidak ada lead — bukan CPL tak hingga, tapi temuan. */
+	borosTanpaLead: boolean;
+	/** Channel dari sumber yang tidak dikenal taksonomi di atas. */
+	takDikenal: boolean;
+}
+
+export function saringLead(
+	rows: RekapLeadHarian[],
+	opsi: { merek: string; dari: string; sampai: string }
+): RekapLeadHarian[] {
+	return rows.filter(
+		(r) =>
+			r.date >= opsi.dari &&
+			r.date <= opsi.sampai &&
+			(opsi.merek === 'ALL' || r.brand === opsi.merek)
+	);
+}
+
+export function perKanalAkuisisi(
+	rows: RekapLeadHarian[],
+	biaya: Partial<Record<EmberBiaya, number>>
+): BarisLeadKanal[] {
+	const jumlah = new Map<string, number>();
+	for (const r of rows) jumlah.set(r.kanal, (jumlah.get(r.kanal) ?? 0) + r.leads);
+
+	const dikenal = new Set(KANAL_AKUISISI.map((k) => k.nama));
+	const urut: KanalAkuisisi[] = [
+		...KANAL_AKUISISI,
+		...[...jumlah.keys()]
+			.filter((n) => !dikenal.has(n))
+			.sort()
+			.map((nama) => ({ nama, ember: null }))
+	];
+
+	const total = [...jumlah.values()].reduce((a, b) => a + b, 0);
+
+	return urut.map((k) => {
+		const leads = jumlah.get(k.nama) ?? 0;
+		const cost = k.ember ? (biaya[k.ember] ?? 0) : null;
+		return {
+			nama: k.nama,
+			berbayar: k.ember != null,
+			leads,
+			porsi: total > 0 ? leads / total : 0,
+			cost,
+			cpl: cost != null && cost > 0 && leads > 0 ? cost / leads : null,
+			borosTanpaLead: cost != null && cost > 0 && leads === 0,
+			takDikenal: !dikenal.has(k.nama)
+		};
+	});
+}
+
+export function totalLead(baris: BarisLeadKanal[]): {
+	leads: number;
+	cost: number;
+	cpl: number | null;
+} {
+	const leads = baris.reduce((a, b) => a + b.leads, 0);
+	const cost = baris.reduce((a, b) => a + (b.cost ?? 0), 0);
+	return { leads, cost, cpl: cost > 0 && leads > 0 ? cost / leads : null };
+}
+
+export function csvLead(baris: BarisLeadKanal[]): string {
+	const kepala = ['Channel akuisisi', 'Berbayar', 'Jumlah lead', 'Porsi', 'Marketing cost (IDR)', 'Cost per lead (IDR)'];
+	const isi = baris.map((b) => [
+		b.nama,
+		b.berbayar ? 'ya' : 'tidak',
+		b.leads,
+		b.porsi,
+		b.cost ?? '',
+		b.cpl ?? ''
+	]);
+	return keCsv([kepala, ...isi]);
+}
