diff --git a/backend/internal/service/gift_card_service.go b/backend/internal/service/gift_card_service.go
new file mode 100644
index 00000000..eb28476e
--- /dev/null
+++ b/backend/internal/service/gift_card_service.go
@@ -0,0 +1,83 @@
+package service
+
+import (
+	"context"
+	"errors"
+	"time"
+
+	"github.com/google/uuid"
+
+	"github.com/kitapos/kitapos/internal/repository"
+)
+
+// These are developer-facing sentinels, so the handler that lands next must map each one to
+// Indonesian copy plus a code (as writeLoyaltyError does) and never forward err.Error().
+var (
+	ErrGiftCardNotFound      = errors.New("gift card: code not found")
+	ErrGiftCardExpired       = errors.New("gift card: card has expired")
+	ErrGiftCardBalanceShort  = errors.New("gift card: balance is less than the amount redeemed")
+	ErrGiftCardAmountInvalid = errors.New("gift card: amount must be above zero")
+)
+
+// GiftCard is the slice of the row this service decides on. It moves to the domain package when
+// the repository and its migration land.
+type GiftCard struct {
+	ID      uuid.UUID
+	Code    string
+	Balance int64
+	// Nil means the card never expires.
+	ExpiresAt *time.Time
+}
+
+type giftCardStore interface {
+	ByCode(ctx context.Context, code string) (*GiftCard, error)
+	// Redeem decrements the balance in ONE statement guarded by `balance >= amount`, and answers
+	// repository.ErrConflict when that guard refuses. Two terminals redeeming the same card at
+	// once is the ordinary case here, and a read-then-write in this service would let both pass.
+	Redeem(ctx context.Context, cardID uuid.UUID, amount int64) error
+}
+
+type GiftCardService struct {
+	cards giftCardStore
+	// now is injected so the expiry branch is testable without waiting for a clock.
+	now func() time.Time
+}
+
+func NewGiftCardService(cards giftCardStore) *GiftCardService {
+	return &GiftCardService{cards: cards, now: time.Now}
+}
+
+// Redeem spends amount (BIGINT rupiah) off the card the code names. Expiry is settled here and
+// the balance in the statement: the first needs a reason the caller can read, the second needs to
+// be race-proof, and only the store can be both.
+func (s *GiftCardService) Redeem(ctx context.Context, code string, amount int64) error {
+	if amount <= 0 {
+		return ErrGiftCardAmountInvalid
+	}
+	normalized := NormalizeCode(code)
+	if normalized == "" {
+		return ErrGiftCardNotFound
+	}
+
+	card, err := s.cards.ByCode(ctx, normalized)
+	if errors.Is(err, repository.ErrNotFound) {
+		return ErrGiftCardNotFound
+	}
+	if err != nil {
+		return err
+	}
+	if card.ExpiresAt != nil && !card.ExpiresAt.After(s.now()) {
+		return ErrGiftCardExpired
+	}
+	if card.Balance < amount {
+		return ErrGiftCardBalanceShort
+	}
+
+	if err := s.cards.Redeem(ctx, card.ID, amount); err != nil {
+		if errors.Is(err, repository.ErrConflict) {
+			return ErrGiftCardBalanceShort
+		}
+		return err
+	}
+	return nil
+}

