+import { describe, expect, it } from 'vitest';
+import { BULAN_AWAL } from './konfigurasi';
+import { daftarBulan, periodeSebelum } from './periode';
+
+describe('periodeSebelum', () => {
+	it('mengambil jendela sepanjang periode yang berakhir sebulan sebelum mulainya', () => {
+		expect(periodeSebelum('2026-04', '2026-09', BULAN_AWAL)).toEqual({
+			dari: '2025-10',
+			sampai: '2026-03'
+		});
+	});
+
+	it('satu bulan dibanding bulan sebelumnya', () => {
+		expect(periodeSebelum('2026-09', '2026-09', BULAN_AWAL)).toEqual({
+			dari: '2026-08',
+			sampai: '2026-08'
+		});
+	});
+
+	it('panjangnya sama dengan periode yang dipilih, termasuk lintas tahun', () => {
+		const dipilih = daftarBulan('2026-01', '2026-12');
+		const lalu = periodeSebelum('2026-01', '2026-12', BULAN_AWAL);
+		expect(lalu).toEqual({ dari: '2025-01', sampai: '2025-12' });
+		expect(daftarBulan(lalu!.dari, lalu!.sampai)).toHaveLength(dipilih.length);
+	});
+
+	it('null kalau jendela pembanding mulai sebelum bulan paling awal yang punya data', () => {
+		expect(periodeSebelum('2024-01', '2024-06', BULAN_AWAL)).toBeNull();
+		expect(periodeSebelum('2024-05', '2024-10', BULAN_AWAL)).toBeNull();
+	});
+
+	it('jendela yang pas berhenti di bulan paling awal masih dipakai', () => {
+		expect(periodeSebelum('2024-07', '2024-12', BULAN_AWAL)).toEqual({
+			dari: '2024-01',
+			sampai: '2024-06'
+		});
+	});
+
+	it('tidak pernah memotong jendela jadi lebih pendek — potongan akan terbaca sebagai penurunan', () => {
+		const lalu = periodeSebelum('2024-06', '2024-12', BULAN_AWAL);
+		expect(lalu).toBeNull();
+	});
+});
