 export function labelPeriode(dari: string, sampai: string): string {
 	return dari === sampai ? labelBulan(dari) : `${labelBulan(dari)} – ${labelBulan(sampai)}`;
 }
+
+/**
+ * Jendela sepanjang `dari..sampai` yang berakhir persis sebelum `dari`.
+ *
+ * `null` bila jendela itu mulai sebelum `awal` — bulan paling awal yang punya
+ * data. Dipotong ke `awal` jendelanya jadi lebih pendek, dan selisih terhadap
+ * periode yang dipilih akan terbaca sebagai penurunan yang tidak terjadi.
+ */
+export function periodeSebelum(
+	dari: string,
+	sampai: string,
+	awal: string
+): { dari: string; sampai: string } | null {
+	const panjang = daftarBulan(dari, sampai).length;
+	if (panjang === 0) return null;
+	const mulai = geserBulan(dari, -panjang);
+	if (mulai < awal) return null;
+
+	return { dari: mulai, sampai: geserBulan(dari, -1) };
+}
