+	const sebelum = $derived(periodeSebelum(dari, sampai, BULAN_AWAL));
+
+	/* `batas: 1` — panel ini hanya memakai `summary`, bukan baris rinciannya. */
+	const opsi = $derived<OpsiAtribusi | null>(
+		sebelum
+			? {
+					brand,
+					dari: sebelum.dari,
+					sampai: sebelum.sampai,
+					dim: 'pic',
+					urut: 'gmv',
+					arah: 'desc',
+					batas: 1,
+					geser: 0,
+					diposting
+				}
+			: null
+	);
+
+	/* Opsi dibaca di scope yang DILACAK, dan hanya panggilannya yang masuk
+	   `untrack`: effect yang membaca opsi di dalam untrack cuma berlangganan ke
+	   `liveApi`, jadi panelnya diam saat filter tanggal berubah. `untrack`
+	   tetap dipakai karena muat() membaca `memuat` secara sinkron — tanpa itu
+	   effect berlangganan ke flag itu dan memanggil muat tanpa henti. */
+	$effect(() => {
+		if (!liveApi) return;
+		const opsiMuat = opsi;
+		if (!opsiMuat) return;
+		untrack(() => void atribusiBanding.muat(opsiMuat));
+	});
+
+	const laporan = $derived(
+		!opsi
+			? null
+			: liveApi
+				? atribusiBanding.mentah
+					? laporanAtribusiDariBE(atribusiBanding.mentah)
+					: null
+				: laporanAtribusiDariBE(contohAtribusi(opsi))
+	);
+	const memuat = $derived(liveApi && atribusiBanding.memuat);
+	const galat = $derived(liveApi ? atribusiBanding.galat : '');
+
+	const BARIS: { kunci: keyof MetrikAtribusi; label: string; uang: boolean }[] = [
+		{ kunci: 'gmv', label: 'GMV', uang: true },
+		{ kunci: 'views', label: 'Views', uang: false },
+		{ kunci: 'produkDilihat', label: 'Produk Dilihat', uang: false },
+		{ kunci: 'video', label: 'Video', uang: false }
+	];
+
+	const perbandingan = $derived(
+		laporan
+			? BARIS.map((b) => {
+					const lalu = laporan.ringkasan[b.kunci];
+					const kini = ringkasan[b.kunci];
+					const format = b.uang ? rupiah : angka;
+					return {
+						...b,
+						lalu: format(lalu),
+						kini: format(kini),
+						delta: lalu > 0 ? ((kini - lalu) / lalu) * 100 : null
+					};
+				})
+			: []
+	);
+</script>
+
+<section class="rounded-[14px] border border-line bg-surface p-4" aria-labelledby="judul-banding" data-uji="banding">
+	<div class="flex flex-wrap items-start justify-between gap-3">
+		<div>
+			<h3 id="judul-banding" class="text-[14px] font-semibold text-ink">Dibanding periode sebelumnya</h3>
+			<p class="mt-0.5 text-[12px] text-muted">
+				{#if sebelum}
+					{labelPeriode(dari, sampai)} dibanding {labelPeriode(sebelum.dari, sebelum.sampai)} — jendela
+					sepanjang periode yang dipilih, persis sebelumnya.{#if memuat}<span role="status"> Memuat…</span>{/if}
+				{:else}
+					Butuh jendela sepanjang periode ini di depannya, dan data video affiliate baru mulai Januari 2024.
+				{/if}
+			</p>
+		</div>
+		{#if laporan && perluTanda(laporan.status)}
+			<span class="flex items-center gap-1.5">
+				<Badge nada={laporan.status === 'known_issue' ? 'negatif' : 'perhatian'}>
+					{laporan.status === 'known_issue' ? 'Masalah diketahui' : 'Estimasi'}
+				</Badge>
+				<span class="text-[11.5px] text-faint">{alasanStatus(laporan.status)}</span>
+			</span>
+		{/if}
+	</div>
+
+	{#if !sebelum}
+		<p class="mt-3 rounded-lg border border-dashed border-line px-3 py-6 text-center text-[12.5px] text-muted" data-uji="banding-mentok">
+			Tidak ada periode pembanding sebelum {labelPeriode(dari, sampai)}. Pilih rentang yang lebih pendek, atau
+			geser mulainya ke bulan yang lebih baru.
+		</p>
+	{:else if !laporan}
+		<div class="mt-3" data-uji={galat ? 'banding-galat' : 'banding-memuat'}>
+			<KartuKeadaan
+				memuat={menungguData(liveApi, laporan, galat)}
+				{galat}
+				ulang={() => atribusiBanding.ulang()}
+				judul="pembanding periode sebelumnya"
+				sumber="partners/attribution"
+				tinggi="9rem"
+			/>
+		</div>
+	{:else if !laporan.ada}
+		<p class="mt-3 rounded-lg border border-dashed border-line px-3 py-6 text-center text-[12.5px] text-muted" data-uji="banding-kosong">
+			Belum ada data atribusi {brand} untuk {labelPeriode(sebelum.dari, sebelum.sampai)}, jadi periode ini tidak
+			ada pembandingnya.
+		</p>
+	{:else}
+		<ul
+			class="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-4"
+			aria-label="Perbandingan dengan periode sebelumnya"
+			aria-busy={memuat}
+			class:opacity-70={memuat}
+		>
+			{#each perbandingan as b (b.kunci)}
+				<li class="rounded-lg bg-raised px-3 py-2">
+					<span class="block text-[12px] text-muted">{b.label}</span>
+					<span class="tnum block text-[13.5px] font-semibold text-ink">{b.kini}</span>
+					<span class="mt-0.5 flex flex-wrap items-center gap-x-1.5 text-[11.5px] text-faint">
+						<span class="tnum">dari {b.lalu}</span>
+						{#if b.delta !== null}
+							<BadgeDelta nilai={b.delta} satuan="%" />
+						{:else}
+							<span>belum ada angka di periode pembanding</span>
+						{/if}
+					</span>
+				</li>
+			{/each}
+		</ul>
+	{/if}
+</section>
