new file mode 100644
index 00000000..d1c71f44
--- /dev/null
+++ b/backend/internal/service/gift_card_service.go
@@ -0,0 +1,118 @@
+package service
+
+import (
+	"context"
+	"errors"
+	"strings"
+	"time"
+
+	"github.com/google/uuid"
+
+	"github.com/kitapos/kitapos/internal/domain"
+	"github.com/kitapos/kitapos/internal/repository"
+)
+
+var (
+	ErrGiftCardCodeEmpty     = errors.New("kode kartu hadiah wajib diisi")
+	ErrGiftCardNotFound      = errors.New("kode kartu hadiah tidak ditemukan")
+	ErrGiftCardInactive      = errors.New("kartu hadiah tidak aktif")
+	ErrGiftCardExpired       = errors.New("kartu hadiah sudah kedaluwarsa")
+	ErrGiftCardInsufficient  = errors.New("saldo kartu hadiah tidak cukup")
+	ErrGiftCardAmountInvalid = errors.New("nominal penukaran harus lebih dari nol")
+)
+
+// GiftCard is a placeholder for the row the repository will return; it moves to
+// internal/domain together with the migration that creates the table.
+type GiftCard struct {
+	ID        uuid.UUID
+	Code      string
+	Balance   int64
+	IsActive  bool
+	ExpiresAt *time.Time
+}
+
+func (c *GiftCard) expired(now time.Time) bool {
+	return c.ExpiresAt != nil && !now.Before(*c.ExpiresAt)
+}
+
+type GiftCardRepository interface {
+	GetByCode(ctx context.Context, code string) (*GiftCard, error)
+
+	// Debit subtracts amount in ONE conditional statement whose WHERE repeats
+	// every refusal below (active, unexpired, balance >= amount) and reports
+	// whether it applied. Reading the balance in Go and writing it back would
+	// let two terminals redeeming the same card each pass the check and spend
+	// the balance twice, so the guard has to live inside the statement.
+	Debit(ctx context.Context, id uuid.UUID, amount int64, now time.Time) (bool, error)
+}
+
+type GiftCardService struct {
+	repo GiftCardRepository
+	now  func() time.Time
+}
+
+func NewGiftCardService(repo GiftCardRepository) *GiftCardService {
+	return &GiftCardService{repo: repo, now: time.Now}
+}
+
+func (s *GiftCardService) Redeem(ctx context.Context, code string, amount int64) error {
+	code = strings.TrimSpace(code)
+	if code == "" {
+		return ErrGiftCardCodeEmpty
+	}
+	if amount <= 0 {
+		return ErrGiftCardAmountInvalid
+	}
+	// Money is BIGINT IDR, and a redeem nets off a bill total, so anything the
+	// money formula cannot carry is refused here rather than wrapped silently.
+	if err := domain.ValidateBillAmount(amount); err != nil {
+		return err
+	}
+
+	card, err := s.repo.GetByCode(ctx, code)
+	if errors.Is(err, repository.ErrNotFound) {
+		return ErrGiftCardNotFound
+	}
+	if err != nil {
+		return err
+	}
+	now := s.now()
+	if refusal := redeemRefusal(card, amount, now); refusal != nil {
+		return refusal
+	}
+
+	ok, err := s.repo.Debit(ctx, card.ID, amount, now)
+	if err != nil {
+		return err
+	}
+	if ok {
+		return nil
+	}
+
+	// Zero rows means the card changed between the read and the write, so the
+	// reason is re-derived from a fresh row instead of guessing which guard bit.
+	fresh, err := s.repo.GetByCode(ctx, code)
+	if errors.Is(err, repository.ErrNotFound) {
+		return ErrGiftCardNotFound
+	}
+	if err != nil {
+		return err
+	}
+	if refusal := redeemRefusal(fresh, amount, s.now()); refusal != nil {
+		return refusal
+	}
+	return ErrGiftCardInsufficient
+}
+
+func redeemRefusal(c *GiftCard, amount int64, now time.Time) error {
+	if !c.IsActive {
+		return ErrGiftCardInactive
+	}
+	if c.expired(now) {
+		return ErrGiftCardExpired
+	}
+	if c.Balance < amount {
+		return ErrGiftCardInsufficient
+	}
+	return nil
+}
diff --git a/backend/internal/service/gift_card_service_test.go b/backend/internal/service/gift_card_service_test.go
new file mode 100644
index 00000000..6e2d69b1
--- /dev/null
+++ b/backend/internal/service/gift_card_service_test.go
@@ -0,0 +1,174 @@
+package service
+
+import (
+	"context"
+	"errors"
+	"testing"
+	"time"
+
+	"github.com/google/uuid"
+
+	"github.com/kitapos/kitapos/internal/domain"
+	"github.com/kitapos/kitapos/internal/repository"
+)
+
+type fakeGiftCardRepo struct {
+	card   *GiftCard
+	debits []int64
+	// swap replaces the row after the first read, standing in for another
+	// terminal that drained or expired the card mid-redeem.
+	swap *GiftCard
+	read int
+}
+
+func (f *fakeGiftCardRepo) GetByCode(_ context.Context, code string) (*GiftCard, error) {
+	f.read++
+	if f.read > 1 && f.swap != nil {
+		return f.swap, nil
+	}
+	if f.card == nil || f.card.Code != code {
+		return nil, repository.ErrNotFound
+	}
+	return f.card, nil
+}
+
+func (f *fakeGiftCardRepo) Debit(_ context.Context, _ uuid.UUID, amount int64, now time.Time) (bool, error) {
+	f.debits = append(f.debits, amount)
+	c := f.card
+	if f.swap != nil {
+		c = f.swap
+	}
+	if !c.IsActive || c.expired(now) || c.Balance < amount {
+		return false, nil
+	}
+	c.Balance -= amount
+	return true, nil
+}
+
+func liveCard(balance int64, expires *time.Time) *GiftCard {
+	return &GiftCard{ID: uuid.New(), Code: "KADO-7731", Balance: balance, IsActive: true, ExpiresAt: expires}
+}
+
+func TestRedeemDebitsAndRefuses(t *testing.T) {
+	now := time.Date(2026, 10, 8, 14, 0, 0, 0, time.UTC)
+	past := now.Add(-time.Hour)
+	future := now.Add(24 * time.Hour)
+
+	tests := []struct {
+		name   string
+		card   *GiftCard
+		amount int64
+		want   error
+	}{
+		{"saldo cukup", liveCard(150_000, &future), 50_000, nil},
+		{"saldo pas", liveCard(50_000, &future), 50_000, nil},
+		{"tanpa kedaluwarsa", liveCard(50_000, nil), 50_000, nil},
+		{"saldo kurang", liveCard(40_000, &future), 50_000, ErrGiftCardInsufficient},
+		{"saldo nol", liveCard(0, &future), 1, ErrGiftCardInsufficient},
+		{"kedaluwarsa", liveCard(500_000, &past), 50_000, ErrGiftCardExpired},
+		{"kedaluwarsa tepat sekarang", liveCard(500_000, &now), 50_000, ErrGiftCardExpired},
+		{"nonaktif", &GiftCard{ID: uuid.New(), Code: "KADO-7731", Balance: 500_000}, 50_000, ErrGiftCardInactive},
+		{"nominal nol", liveCard(500_000, &future), 0, ErrGiftCardAmountInvalid},
+		{"nominal negatif", liveCard(500_000, &future), -50_000, ErrGiftCardAmountInvalid},
+	}
+
+	for _, tc := range tests {
+		t.Run(tc.name, func(t *testing.T) {
+			repo := &fakeGiftCardRepo{card: tc.card}
+			svc := &GiftCardService{repo: repo, now: func() time.Time { return now }}
+			before := tc.card.Balance
+
+			err := svc.Redeem(context.Background(), "KADO-7731", tc.amount)
+
+			if !errors.Is(err, tc.want) {
+				t.Fatalf("Redeem = %v, mau %v", err, tc.want)
+			}
+			if tc.want == nil {
+				if got := tc.card.Balance; got != before-tc.amount {
+					t.Fatalf("saldo = %d, mau %d", got, before-tc.amount)
+				}
+				return
+			}
+			// A refusal must leave the balance where it was, and anything
+			// refusable before the write must never reach the repository.
+			if got := tc.card.Balance; got != before {
+				t.Fatalf("penolakan mengubah saldo: %d, mau %d", got, before)
+			}
+			if len(repo.debits) != 0 {
+				t.Fatalf("penolakan tetap memanggil Debit: %v", repo.debits)
+			}
+		})
+	}
+}
+
+func TestRedeemEmptyCodeAndUnknownCode(t *testing.T) {
+	now := time.Now()
+	for _, code := range []string{"", "   ", "\t"} {
+		repo := &fakeGiftCardRepo{card: liveCard(500_000, nil)}
+		svc := &GiftCardService{repo: repo, now: func() time.Time { return now }}
+		if err := svc.Redeem(context.Background(), code, 10_000); !errors.Is(err, ErrGiftCardCodeEmpty) {
+			t.Fatalf("kode %q: %v, mau ErrGiftCardCodeEmpty", code, err)
+		}
+		if repo.read != 0 {
+			t.Fatalf("kode %q menyentuh repo", code)
+		}
+	}
+
+	repo := &fakeGiftCardRepo{card: liveCard(500_000, nil)}
+	svc := &GiftCardService{repo: repo, now: func() time.Time { return now }}
+	if err := svc.Redeem(context.Background(), "KADO-0000", 10_000); !errors.Is(err, ErrGiftCardNotFound) {
+		t.Fatalf("kode asing: %v, mau ErrGiftCardNotFound", err)
+	}
+}
+
+func TestRedeemTrimsCodeBeforeLookup(t *testing.T) {
+	now := time.Now()
+	card := liveCard(100_000, nil)
+	svc := &GiftCardService{repo: &fakeGiftCardRepo{card: card}, now: func() time.Time { return now }}
+	if err := svc.Redeem(context.Background(), "  KADO-7731  ", 10_000); err != nil {
+		t.Fatalf("Redeem = %v, mau nil", err)
+	}
+	if card.Balance != 90_000 {
+		t.Fatalf("saldo = %d, mau 90000", card.Balance)
+	}
+}
+
+// A conditional Debit that applies to zero rows must name the reason the fresh
+// row carries, never the one read before the race.
+func TestRedeemLosingRaceReportsFreshReason(t *testing.T) {
+	now := time.Date(2026, 10, 8, 14, 0, 0, 0, time.UTC)
+	past := now.Add(-time.Hour)
+
+	drained := liveCard(0, nil)
+	repo := &fakeGiftCardRepo{card: liveCard(100_000, nil), swap: drained}
+	svc := &GiftCardService{repo: repo, now: func() time.Time { return now }}
+	if err := svc.Redeem(context.Background(), "KADO-7731", 50_000); !errors.Is(err, ErrGiftCardInsufficient) {
+		t.Fatalf("kalah balapan saldo: %v, mau ErrGiftCardInsufficient", err)
+	}
+	if len(repo.debits) != 1 {
+		t.Fatalf("Debit dipanggil %d kali, mau 1", len(repo.debits))
+	}
+
+	expiredMid := liveCard(500_000, &past)
+	repo = &fakeGiftCardRepo{card: liveCard(500_000, nil), swap: expiredMid}
+	svc = &GiftCardService{repo: repo, now: func() time.Time { return now }}
+	if err := svc.Redeem(context.Background(), "KADO-7731", 50_000); !errors.Is(err, ErrGiftCardExpired) {
+		t.Fatalf("kalah balapan kedaluwarsa: %v, mau ErrGiftCardExpired", err)
+	}
+	if expiredMid.Balance != 500_000 {
+		t.Fatalf("kartu kedaluwarsa terdebit: %d", expiredMid.Balance)
+	}
+}
+
+func TestRedeemRefusesAmountBeyondMoneyFormula(t *testing.T) {
+	now := time.Now()
+	card := liveCard(500_000, nil)
+	svc := &GiftCardService{repo: &fakeGiftCardRepo{card: card}, now: func() time.Time { return now }}
+	err := svc.Redeem(context.Background(), "KADO-7731", 1<<62)
+	if !errors.Is(err, domain.ErrOrderAmountOutOfRange) {
+		t.Fatalf("Redeem = %v, mau ErrOrderAmountOutOfRange", err)
+	}
+	if card.Balance != 500_000 {
+		t.Fatalf("saldo berubah: %d", card.Balance)
+	}
+}
