+import { describe, expect, it } from 'vitest';
+import { ringkasanAkun } from './affiliate';
+import type { JawabanAffiliate, TitikBulananAffiliate } from '$lib/api/tipe';
+
+function titik(month: string, n: number): TitikBulananAffiliate {
+	return {
+		month,
+		videos: n,
+		viral: Math.floor(n / 5),
+		video_views: n * 10_000,
+		products_viewed: n * 1_000,
+		product_clicks: n * 120,
+		gmv: n * 5_000_000
+	};
+}
+
+function jawaban(bulan: TitikBulananAffiliate[]): JawabanAffiliate {
+	return {
+		status: 'live',
+		brand: 'Jiera',
+		from: '2026-05-01',
+		to: '2026-10-31',
+		summary: {
+			videos: 0,
+			viral: 0,
+			creators: 0,
+			video_views: 0,
+			products_viewed: 0,
+			product_clicks: 0,
+			gmv: 0
+		},
+		monthly: bulan,
+		rows: [],
+		charts: {
+			monthly: { labels: [], series: [] },
+			funnel: { labels: [], series: [] },
+			classification: { labels: [], series: [] }
+		}
+	};
+}
+
+describe('ringkasanAkun', () => {
+	const isi = jawaban([titik('2026-05', 10), titik('2026-06', 20), titik('2026-07', 30)]);
+
+	it('menjumlahkan hanya bulan di dalam rentang', () => {
+		const r = ringkasanAkun(isi, '2026-06', '2026-07');
+		expect(r.bulan).toEqual(['2026-06', '2026-07']);
+		expect(r.video).toBe(50);
+		expect(r.klikProduk).toBe(6_000);
+		expect(r.gmv).toBe(250_000_000);
+	});
+
+	it('bergeser saat rentangnya dipersempit', () => {
+		expect(ringkasanAkun(isi, '2026-05', '2026-07').video).toBe(60);
+		expect(ringkasanAkun(isi, '2026-07', '2026-07').video).toBe(30);
+	});
+
+	it('menerima bulan BE yang datang sebagai tanggal penuh', () => {
+		const penuh = jawaban([titik('2026-06-01', 20)]);
+		expect(ringkasanAkun(penuh, '2026-06', '2026-06').bulan).toEqual(['2026-06']);
+	});
+
+	it('kosong, bukan nol palsu, saat tidak ada bulan yang cocok', () => {
+		const r = ringkasanAkun(isi, '2026-09', '2026-10');
+		expect(r.bulan).toEqual([]);
+		expect(r.video).toBe(0);
+	});
+
+	it('tahan terhadap payload yang belum datang', () => {
+		expect(ringkasanAkun(null, '2026-05', '2026-10').bulan).toEqual([]);
+	});
+});
