 }
+
+export interface RingkasanAkun {
+	bulan: string[];
+	video: number;
+	viral: number;
+	views: number;
+	produkDilihat: number;
+	klikProduk: number;
+	gmv: number;
+}
+
+/**
+ * Ringkasan akun affiliate dijumlahkan dari deret bulanan, bukan dibaca dari
+ * `summary` BE — `summary` memakai rentang yang diminta, dan jalur Plan design
+ * memakai katalog bulan tetap. Satu penjumlahan untuk kedua sumber berarti
+ * pemilih bulan menggeser angka yang sama di kedua mode, dan tidak ada bulan
+ * di luar rentang yang ikut terhitung kalau BE suatu saat mengirim ekor.
+ */
+export function ringkasanAkun(isi: JawabanAffiliate | null, dari: string, sampai: string): RingkasanAkun {
+	const dalam = (isi?.monthly ?? []).filter((t) => {
+		const k = kunciBulan(t.month ?? '');
+		return !!k && k >= dari && k <= sampai;
+	});
+
+	return {
+		bulan: dalam.map((t) => kunciBulan(t.month) ?? t.month),
+		video: dalam.reduce((a, t) => a + angka(t.videos), 0),
+		viral: dalam.reduce((a, t) => a + angka(t.viral), 0),
+		views: dalam.reduce((a, t) => a + angka(t.video_views), 0),
+		produkDilihat: dalam.reduce((a, t) => a + angka(t.products_viewed), 0),
+		klikProduk: dalam.reduce((a, t) => a + angka(t.product_clicks), 0),
+		gmv: dalam.reduce((a, t) => a + angka(t.gmv), 0)
+	};
+}
