+/** Durasi pendek untuk hitungan "x lalu" dan hitung mundur: `45s`, `4m 05s`, `1j 12m`. */
+export function durasiRingkas(detik: number): string {
+	const d = Math.max(0, Math.round(detik));
+	if (d < 60) return `${d}s`;
+
+	const menit = Math.floor(d / 60);
+	if (menit < 60) return `${menit}m ${String(d % 60).padStart(2, '0')}s`;
+
+	return `${Math.floor(menit / 60)}j ${String(menit % 60).padStart(2, '0')}m`;
+}
