+import { browser } from '$app/environment';
+
+/**
+ * Penyegaran otomatis layar yang menarik angka Live.
+ *
+ * Tujuannya satu: orang yang menonton layar ini tidak perlu menekan muat
+ * ulang. Yang dibangun di sini **penarikan berulang**, bukan kanal dorong —
+ * BE Funnel tidak punya satu pun endpoint SSE/WebSocket untuk data (aliran
+ * SSE di `klien.ts` milik proksi AI, bukan BE), dan hasil build repo ini
+ * statis murni tanpa runtime Node. Jadi "tanpa perlu refresh" di sini berarti
+ * halaman yang menarik ulang sendiri, dengan jarak yang kelihatan.
+ *
+ * Tiga penjaga, dan masing-masing pernah jadi bug di repo ini:
+ *
+ * - **Tab yang tidak terlihat tidak menarik apa pun.** Satu putaran layar CEO
+ *   adalah 11 panggilan BE, sebagiannya berbatas 45 detik. Tab yang terbuka
+ *   seminggu di latar belakang adalah badai permintaan yang tak dilihat siapa
+ *   pun — kelas yang sama dengan `545ad8e`.
+ * - **Putaran yang masih berjalan tidak ditimpa putaran baru.** `muat()` punya
+ *   penjaganya sendiri, tapi penjaga di sini yang membuat jaraknya benar.
+ * - **Jarak dihitung dari SELESAINYA putaran terakhir**, bukan dari mulainya.
+ *   BE yang lambat melebarkan jaraknya sendiri alih-alih dikejar timer.
+ *
+ * Yang tidak dibangun: deteksi "ada baris baru". BE tidak mengirim peristiwa,
+ * jadi satu-satunya cara mengetahui ada angka baru adalah menarik dan
+ * membandingkan — dan itu persis yang dilakukan `muat()`.
+ */
+
+export const JEDA_PILIHAN = [
+	{ detik: 60, label: '1 menit' },
+	{ detik: 300, label: '5 menit' },
+	{ detik: 900, label: '15 menit' }
+] as const;
+
+const KUNCI = 'hegemoni-segar';
+const JEDA_BAWAAN = 300;
+
+/** Satu detak; cukup halus untuk hitungan di layar, cukup murah untuk diam. */
+const DETAK_MS = 1000;
+
+export interface KeadaanJadwal {
+	aktif: boolean;
+	tersembunyi: boolean;
+	berjalan: boolean;
+	/** Epoch ms saat putaran terakhir selesai; null berarti belum ada acuan. */
+	terakhir: number | null;
+	sekarang: number;
+	jedaDetik: number;
+}
+
+/**
+ * Keputusan "tarik sekarang atau tidak".
+ *
+ * Dipisah dari timer karena inilah bagian yang bisa salah tanpa terlihat:
+ * timer tetap berdetak, layar tetap hidup, dan yang hilang hanya penarikannya.
+ * Fungsi murni supaya bisa diuji tanpa browser.
+ */
+export function perluTarik(k: KeadaanJadwal): boolean {
+	if (!k.aktif || k.tersembunyi || k.berjalan) return false;
+	if (k.terakhir === null) return false;
+
+	return k.sekarang - k.terakhir >= k.jedaDetik * 1000;
+}
+
+function jedaSah(n: unknown): number | null {
+	return JEDA_PILIHAN.some((p) => p.detik === n) ? (n as number) : null;
+}
+
+class Segar {
+	aktif = $state(true);
+	jedaDetik = $state<number>(JEDA_BAWAAN);
+
+	/** Epoch ms selesainya putaran terakhir. */
+	terakhir = $state<number | null>(null);
+	/** Jam dinding yang ikut berdetak, supaya label "x lalu" bergerak sendiri. */
+	sekarang = $state(Date.now());
+	berjalan = $state(false);
+	tersembunyi = $state(false);
+	/** Galat putaran terakhir; angka di layar tetap yang lama. */
+	galat = $state('');
+
+	private timer: ReturnType<typeof setInterval> | null = null;
+	private tugas: (() => Promise<unknown>) | null = null;
+	private lepasVisibilitas: (() => void) | null = null;
+
+	/**
+	 * Mulai menjadwal `tugas`. Mengembalikan penghenti, jadi pemanggilnya bisa
+	 * langsung `return segar.mulai(...)` dari dalam `$effect`.
+	 *
+	 * `terakhir` disetel sekarang karena halaman baru saja memuat sendiri saat
+	 * dipasang: acuannya adalah data yang sudah ada di layar, bukan nol.
+	 */
+	mulai(tugas: () => Promise<unknown>): () => void {
+		if (!browser) return () => {};
+
+		this.henti();
+		this.bacaPilihan();
+		this.tugas = tugas;
+		this.terakhir = Date.now();
+		this.sekarang = this.terakhir;
+		this.tersembunyi = document.visibilityState === 'hidden';
+
+		const padaVisibilitas = () => {
+			this.tersembunyi = document.visibilityState === 'hidden';
+			this.sekarang = Date.now();
+		};
+		document.addEventListener('visibilitychange', padaVisibilitas);
+		this.lepasVisibilitas = () => document.removeEventListener('visibilitychange', padaVisibilitas);
+
+		this.timer = setInterval(() => this.detak(), DETAK_MS);
+
+		return () => this.henti();
+	}
+
+	henti() {
+		if (this.timer !== null) clearInterval(this.timer);
+		this.timer = null;
+		this.lepasVisibilitas?.();
+		this.lepasVisibilitas = null;
+		this.tugas = null;
+	}
+
+	/** Tarik sekarang, lepas dari jadwal — tombol "Segarkan" memakai ini. */
+	async jalankan(): Promise<void> {
+		if (!this.tugas || this.berjalan) return;
+
+		this.berjalan = true;
+		try {
+			await this.tugas();
+			this.galat = '';
+		} catch (e) {
+			this.galat = e instanceof Error ? e.message : 'Penarikan terakhir gagal.';
+		} finally {
+			this.berjalan = false;
+			this.terakhir = Date.now();
+			this.sekarang = this.terakhir;
+		}
+	}
+
+	setelAktif(v: boolean) {
+		this.aktif = v;
+		// Dinyalakan ulang menarik dari sekarang, bukan membayar utang jeda yang
+		// lewat selagi mati.
+		if (v) this.terakhir = Date.now();
+		this.simpanPilihan();
+	}
+
+	setelJeda(detik: number) {
+		this.jedaDetik = jedaSah(detik) ?? JEDA_BAWAAN;
+		this.simpanPilihan();
+	}
+
+	private detak() {
+		this.sekarang = Date.now();
+		this.tersembunyi = document.visibilityState === 'hidden';
+
+		if (
+			perluTarik({
+				aktif: this.aktif,
+				tersembunyi: this.tersembunyi,
+				berjalan: this.berjalan,
+				terakhir: this.terakhir,
+				sekarang: this.sekarang,
+				jedaDetik: this.jedaDetik
+			})
+		) {
+			void this.jalankan();
+		}
+	}
+
+	private bacaPilihan() {
+		try {
+			const mentah = localStorage.getItem(KUNCI);
+			if (!mentah) return;
+
+			const isi = JSON.parse(mentah) as { aktif?: unknown; jedaDetik?: unknown };
+			if (typeof isi.aktif === 'boolean') this.aktif = isi.aktif;
+			const jeda = jedaSah(isi.jedaDetik);
+			if (jeda !== null) this.jedaDetik = jeda;
+		} catch {
+			// Simpanan diblokir atau isinya rusak: pakai bawaan, jangan jatuh.
+		}
+	}
+
+	private simpanPilihan() {
+		try {
+			localStorage.setItem(KUNCI, JSON.stringify({ aktif: this.aktif, jedaDetik: this.jedaDetik }));
+		} catch {
+			// Pilihannya tetap berlaku sesi ini, hanya tidak diingat.
+		}
+	}
+}
+
+export const segar = new Segar();
