diff --git a/backend/internal/service/gift_card_service.go b/backend/internal/service/gift_card_service.go
new file mode 100644
index 00000000..098b2615
--- /dev/null
+++ b/backend/internal/service/gift_card_service.go
@@ -0,0 +1,92 @@
+package service
+
+import (
+	"context"
+	"errors"
+	"strings"
+	"time"
+
+	"github.com/kitapos/kitapos/internal/domain"
+)
+
+// A gift card spent against a bill. The read before the debit exists only to tell the
+// cashier WHICH refusal they hit: the guard that actually holds is the conditional debit,
+// which carries its own balance and expiry test, so two terminals redeeming the same card
+// at once cannot both pass. A read-then-write pair without that condition double-spends.
+
+var (
+	ErrGiftCardsUnavailable = errors.New("kartu hadiah belum tersedia")
+	ErrGiftCardNotFound     = errors.New("kode kartu hadiah tidak ditemukan")
+	ErrGiftCardExpired      = errors.New("kartu hadiah sudah kadaluarsa")
+	ErrGiftCardShort        = errors.New("saldo kartu hadiah tidak mencukupi")
+	ErrGiftCardAmount       = errors.New("nominal penukaran harus di atas nol")
+)
+
+type GiftCard struct {
+	Code      string     `json:"code"`
+	Balance   int64      `json:"balance"`
+	ExpiresAt *time.Time `json:"expires_at,omitempty"`
+}
+
+// Expired is false for a card with no expiry at all. The boundary instant counts as
+// expired so a card valid "until" a date stops working at that date, not a day after.
+func (g GiftCard) Expired(now time.Time) bool {
+	return g.ExpiresAt != nil && !g.ExpiresAt.After(now)
+}
+
+type GiftCardStore interface {
+	ByCode(ctx context.Context, code string) (*GiftCard, error)
+	// Debit subtracts amount only while the row still covers it and has not expired at
+	// now, answering false when it no longer qualifies. Both tests belong in the same
+	// statement as the subtraction: a caller that checked them first has already raced.
+	Debit(ctx context.Context, code string, amount int64, now time.Time) (bool, error)
+}
+
+type GiftCardService struct {
+	store GiftCardStore
+}
+
+func NewGiftCardService(store GiftCardStore) *GiftCardService {
+	return &GiftCardService{store: store}
+}
+
+func (s *GiftCardService) Redeem(ctx context.Context, code string, amount int64) error {
+	if s.store == nil {
+		return ErrGiftCardsUnavailable
+	}
+	if amount <= 0 {
+		return ErrGiftCardAmount
+	}
+	if err := domain.ValidateBillAmount(amount); err != nil {
+		return err
+	}
+	code = strings.ToUpper(strings.TrimSpace(code))
+	if code == "" {
+		return ErrGiftCardNotFound
+	}
+
+	card, err := s.store.ByCode(ctx, code)
+	if err != nil {
+		return err
+	}
+	if card == nil {
+		return ErrGiftCardNotFound
+	}
+	now := time.Now()
+	if card.Expired(now) {
+		return ErrGiftCardExpired
+	}
+	if card.Balance < amount {
+		return ErrGiftCardShort
+	}
+
+	ok, err := s.store.Debit(ctx, code, amount, now)
+	if err != nil {
+		return err
+	}
+	if !ok {
+		// The row qualified a moment ago, so another terminal spent it in between.
+		return ErrGiftCardShort
+	}
+	return nil
+}
