@@ -0,0 +1,74 @@
+package service
+
+import (
+	"context"
+	"errors"
+	"testing"
+	"time"
+)
+
+type fakeGiftCards struct {
+	card    *GiftCard
+	debited int64
+	allow   bool
+}
+
+func (f *fakeGiftCards) ByCode(ctx context.Context, code string) (*GiftCard, error) {
+	if f.card == nil || f.card.Code != code {
+		return nil, nil
+	}
+	return f.card, nil
+}
+
+func (f *fakeGiftCards) Debit(ctx context.Context, code string, amount int64, now time.Time) (bool, error) {
+	if !f.allow {
+		return false, nil
+	}
+	f.debited = amount
+	return true, nil
+}
+
+func TestGiftCardRedeem(t *testing.T) {
+	future := time.Now().Add(48 * time.Hour)
+	past := time.Now().Add(-1 * time.Minute)
+
+	cases := []struct {
+		name   string
+		card   *GiftCard
+		allow  bool
+		code   string
+		amount int64
+		want   error
+	}{
+		{"spends a covered card", &GiftCard{Code: "KADO-2026", Balance: 150000, ExpiresAt: &future}, true, " kado-2026 ", 150000, nil},
+		{"no expiry never expires", &GiftCard{Code: "KADO-2026", Balance: 50000}, true, "KADO-2026", 25000, nil},
+		{"balance short of the amount", &GiftCard{Code: "KADO-2026", Balance: 24999, ExpiresAt: &future}, true, "KADO-2026", 25000, ErrGiftCardShort},
+		{"expired card", &GiftCard{Code: "KADO-2026", Balance: 150000, ExpiresAt: &past}, true, "KADO-2026", 25000, ErrGiftCardExpired},
+		{"lost the race to another terminal", &GiftCard{Code: "KADO-2026", Balance: 150000, ExpiresAt: &future}, false, "KADO-2026", 25000, ErrGiftCardShort},
+		{"unknown code", nil, true, "KADO-9999", 25000, ErrGiftCardNotFound},
+		{"zero amount", &GiftCard{Code: "KADO-2026", Balance: 150000}, true, "KADO-2026", 0, ErrGiftCardAmount},
+		{"negative amount", &GiftCard{Code: "KADO-2026", Balance: 150000}, true, "KADO-2026", -5000, ErrGiftCardAmount},
+	}
+
+	for _, tc := range cases {
+		t.Run(tc.name, func(t *testing.T) {
+			store := &fakeGiftCards{card: tc.card, allow: tc.allow}
+			err := NewGiftCardService(store).Redeem(context.Background(), tc.code, tc.amount)
+			if !errors.Is(err, tc.want) {
+				t.Fatalf("got %v, want %v", err, tc.want)
+			}
+			if tc.want == nil && store.debited != tc.amount {
+				t.Fatalf("debited %d, want %d", store.debited, tc.amount)
+			}
+			if tc.want != nil && store.debited != 0 {
+				t.Fatalf("debited %d on a refusal", store.debited)
+			}
+		})
+	}
+}
+
+func TestGiftCardRedeemUnwired(t *testing.T) {
+	if err := (&GiftCardService{}).Redeem(context.Background(), "KADO-2026", 1000); !errors.Is(err, ErrGiftCardsUnavailable) {
+		t.Fatalf("got %v", err)
+	}
+}

diff --git a/backend/internal/service/gift_card_service.go b/backend/internal/service/gift_card_service.go
new file mode 100644
index 00000000..8b0fccfe
--- /dev/null
+++ b/backend/internal/service/gift_card_service.go
@@ -0,0 +1,84 @@
+package service
+
+import (
+	"context"
+	"errors"
+	"strings"
+	"time"
+)
+
+// GiftCard is what redemption needs to decide: how much is left and until when.
+// Balance is rupiah as BIGINT, like every other amount here. A nil ExpiresAt is
+// a card that never expires.
+type GiftCard struct {
+	ID        string
+	Code      string
+	Balance   int64
+	ExpiresAt *time.Time
+}
+
+// GiftCardRepository is the slice of storage this service needs. Debit must be
+// a single conditional statement (`SET balance = balance - $amount WHERE id = $id
+// AND balance >= $amount`) and answer ErrGiftCardInsufficientBalance when it
+// matched no row: two cashiers can scan one card at the same moment, so the read
+// below narrows the error message while the statement is what actually holds.
+type GiftCardRepository interface {
+	GetByCode(ctx context.Context, code string) (*GiftCard, error)
+	Debit(ctx context.Context, cardID string, amount int64) error
+}
+
+// Sentinel errors, in English because the handler maps each one to its own
+// Indonesian sentence and code — never forward err.Error() to writeError.
+var (
+	ErrGiftCardCodeRequired        = errors.New("gift card code is required")
+	ErrGiftCardAmountInvalid       = errors.New("redeemed amount must be above zero")
+	ErrGiftCardNotFound            = errors.New("no gift card with that code")
+	ErrGiftCardExpired             = errors.New("this gift card has expired")
+	ErrGiftCardInsufficientBalance = errors.New("gift card balance is below the redeemed amount")
+)
+
+type GiftCardService struct {
+	repo GiftCardRepository
+	now  func() time.Time
+}
+
+func NewGiftCardService(repo GiftCardRepository) *GiftCardService {
+	return &GiftCardService{repo: repo, now: time.Now}
+}
+
+// Redeem spends amount off the card the code names. Expiry is checked before
+// balance so a card that is both expired and short says the thing the cashier
+// cannot work around.
+func (s *GiftCardService) Redeem(ctx context.Context, code string, amount int64) error {
+	// Codes are read off a printed card and typed by hand, so case and stray
+	// spaces are the cashier's, not the card's.
+	code = strings.ToUpper(strings.TrimSpace(code))
+	if code == "" {
+		return ErrGiftCardCodeRequired
+	}
+	if amount <= 0 {
+		return ErrGiftCardAmountInvalid
+	}
+
+	card, err := s.repo.GetByCode(ctx, code)
+	if err != nil {
+		return err
+	}
+	if card == nil {
+		return ErrGiftCardNotFound
+	}
+	if card.Expired(s.now()) {
+		return ErrGiftCardExpired
+	}
+	if card.Balance < amount {
+		return ErrGiftCardInsufficientBalance
+	}
+
+	return s.repo.Debit(ctx, card.ID, amount)
+}
+
+// Expired is false for a card without an expiry date. The instant itself still
+// counts as valid, so a card expiring at midnight is spendable all day.
+func (c *GiftCard) Expired(now time.Time) bool {
+	return c.ExpiresAt != nil && now.After(*c.ExpiresAt)
+}
diff --git a/backend/internal/service/gift_card_service_test.go b/backend/internal/service/gift_card_service_test.go
new file mode 100644
index 00000000..829116f8
