+++ b/backend/internal/service/gift_card_service_test.go
@@ -0,0 +1,78 @@
+package service
+
+import (
+	"context"
+	"errors"
+	"testing"
+	"time"
+)
+
+type fakeGiftCardRepo struct {
+	card     *GiftCard
+	debited  int64
+	debitErr error
+}
+
+func (f *fakeGiftCardRepo) GetByCode(_ context.Context, code string) (*GiftCard, error) {
+	if f.card == nil || f.card.Code != code {
+		return nil, nil
+	}
+	return f.card, nil
+}
+
+func (f *fakeGiftCardRepo) Debit(_ context.Context, _ string, amount int64) error {
+	f.debited += amount
+	return f.debitErr
+}
+
+func TestRedeem(t *testing.T) {
+	past := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
+	future := time.Date(2027, 1, 1, 0, 0, 0, 0, time.UTC)
+	now := time.Date(2026, 10, 8, 12, 0, 0, 0, time.UTC)
+
+	cases := []struct {
+		name      string
+		card      *GiftCard
+		code      string
+		amount    int64
+		want      error
+		wantSpend int64
+	}{
+		{"spends a live card", &GiftCard{ID: "1", Code: "KADO-7788", Balance: 100_000, ExpiresAt: &future}, "KADO-7788", 40_000, nil, 40_000},
+		{"typed lowercase and padded", &GiftCard{ID: "1", Code: "KADO-7788", Balance: 100_000}, " kado-7788 ", 40_000, nil, 40_000},
+		{"balance below the amount", &GiftCard{ID: "1", Code: "KADO-7788", Balance: 39_999, ExpiresAt: &future}, "KADO-7788", 40_000, ErrGiftCardInsufficientBalance, 0},
+		{"expired beats a short balance", &GiftCard{ID: "1", Code: "KADO-7788", Balance: 0, ExpiresAt: &past}, "KADO-7788", 40_000, ErrGiftCardExpired, 0},
+		{"unknown code", nil, "KADO-0000", 40_000, ErrGiftCardNotFound, 0},
+		{"empty code", nil, "   ", 40_000, ErrGiftCardCodeRequired, 0},
+		{"zero amount", &GiftCard{ID: "1", Code: "KADO-7788", Balance: 100_000}, "KADO-7788", 0, ErrGiftCardAmountInvalid, 0},
+	}
+
+	for _, tc := range cases {
+		t.Run(tc.name, func(t *testing.T) {
+			repo := &fakeGiftCardRepo{card: tc.card}
+			s := NewGiftCardService(repo)
+			s.now = func() time.Time { return now }
+
+			err := s.Redeem(context.Background(), tc.code, tc.amount)
+			if !errors.Is(err, tc.want) {
+				t.Fatalf("got %v, want %v", err, tc.want)
+			}
+			if repo.debited != tc.wantSpend {
+				t.Fatalf("debited %d, want %d", repo.debited, tc.wantSpend)
+			}
+		})
+	}
+}
+
+// The read is a message, not the guard: a card drained between the read and the
+// write still has to come back as insufficient.
+func TestRedeemTrustsTheConditionalDebit(t *testing.T) {
+	repo := &fakeGiftCardRepo{
+		card:     &GiftCard{ID: "1", Code: "KADO-7788", Balance: 100_000},
+		debitErr: ErrGiftCardInsufficientBalance,
+	}
+	s := NewGiftCardService(repo)
+	if err := s.Redeem(context.Background(), "KADO-7788", 40_000); !errors.Is(err, ErrGiftCardInsufficientBalance) {
+		t.Fatalf("got %v, want ErrGiftCardInsufficientBalance", err)
+	}
+}

