+import { readFileSync } from 'node:fs';
+import { describe, expect, it } from 'vitest';
+import { laporanAtribusiDariBE } from '$lib/adapter/affiliate';
+import { contohAtribusi } from '$lib/data/atribusi-affiliate';
+import { ringkasanPeriode } from './ringkasan-periode';
+import type { OpsiAtribusi } from '$lib/state/affiliate.svelte';
+
+const dasar: OpsiAtribusi = {
+	brand: 'Jiera',
+	dari: '2026-04',
+	sampai: '2026-09',
+	dim: 'pic',
+	urut: 'gmv',
+	arah: 'desc',
+	batas: 20,
+	geser: 0,
+	diposting: 'all'
+};
+
+function ringkas(dari: string, sampai: string) {
+	return ringkasanPeriode(laporanAtribusiDariBE(contohAtribusi({ ...dasar, dari, sampai })));
+}
+
+describe('ringkasan periode ikut filter tanggal', () => {
+	it('mengganti bulan berdata dan rata-ratanya saat rentang berubah', () => {
+		const enam = ringkas('2026-04', '2026-09')!;
+		const dua = ringkas('2026-08', '2026-09')!;
+		expect(enam.bulanBerdata).toBe(6);
+		expect(dua.bulanBerdata).toBe(2);
+		expect(dua.bulan.map((b) => b.bulan)).toEqual(['2026-08', '2026-09']);
+		expect(dua.rataGmv).not.toBe(enam.rataGmv);
+	});
+});
+
+/**
+ * Halaman ini memuat BE lewat satu `$effect`. Membaca opsinya DI DALAM
+ * `untrack` membuat efek itu hanya bergantung pada `liveApi`, jadi memindahkan
+ * pemilih tanggal tidak pernah memicu permintaan baru dan angka di layar
+ * tertinggal di periode pertama yang dibuka — tanpa galat dan tanpa gejala di
+ * mode demo, yang tidak pernah memanggil BE sama sekali. Karena itu
+ * penjaganya dipasang di sumbernya, bukan di perilaku.
+ */
+describe('efek pemuat di halaman Affiliate membaca opsinya sebagai dependensi', () => {
+	const berkas = ['src/routes/affiliate/+page.svelte', 'src/lib/ui/affiliate/PanelRincian.svelte'];
+
+	for (const f of berkas) {
+		it(`${f} tidak membaca opsi di dalam untrack`, () => {
+			const isi = readFileSync(f, 'utf8');
+			const efek = [...isi.matchAll(/\$effect\(\(\) => \{([\s\S]*?)\n\t\}\);/g)].map((m) => m[1]);
+			const pemuat = efek.filter((b) => b.includes('untrack('));
+			expect(pemuat.length).toBeGreaterThan(0);
+
+			for (const b of pemuat) {
+				const argumen = [...b.matchAll(/untrack\(\(\) => void [\w.]+\(([\w]*)\)/g)].map((m) => m[1]);
+				for (const a of argumen) {
+					if (!a) continue;
+					expect(b, `argumen "${a}" harus disalin dari luar untrack di dalam efek ini`).toMatch(
+						new RegExp(`const ${a}\\s*=`)
+					);
+				}
+			}
+		});
+	}
+});
