+import { describe, expect, it } from 'vitest';
+import { KANAL } from './konfigurasi';
+import { ringkasanPeriode } from './ringkasan-periode';
+import type { CakupanBulan, LaporanAtribusi, MetrikAtribusi } from './tipe';
+
+function nol(): MetrikAtribusi {
+	return { gmv: 0, views: 0, produkDilihat: 0, video: 0 };
+}
+
+/** GMV per bulan dibagi rata ke tiga kanal, supaya totalnya persis `gmv[i]`. */
+function laporan(
+	bulan: string[],
+	gmv: number[],
+	views: number[],
+	cakupan: Partial<CakupanBulan>[] = []
+): LaporanAtribusi {
+	const seri = KANAL.map(({ kunci }, k) => ({
+		kanal: kunci,
+		nilai: bulan.map((_, i) => ({
+			gmv: k === 0 ? gmv[i] : 0,
+			views: k === 0 ? views[i] : 0,
+			produkDilihat: 0,
+			video: k === 0 ? 2 : 0
+		})),
+		total: nol()
+	}));
+	return {
+		ada: true,
+		status: 'live',
+		brand: 'Jiera',
+		dari: bulan[0] ?? '',
+		sampai: bulan[bulan.length - 1] ?? '',
+		ringkasan: {
+			gmv: gmv.reduce((a, n) => a + n, 0),
+			views: views.reduce((a, n) => a + n, 0),
+			produkDilihat: 0,
+			video: bulan.length * 2
+		},
+		diposting: nol(),
+		bulan,
+		seri,
+		rincian: { dimensi: 'pic', baris: [], total: 0 },
+		teratas: { dimensi: 'pic', baris: [] },
+		cakupan: bulan.map((b, i) => ({
+			bulan: b,
+			sumber: 'marketbridge_daily',
+			hariTerisi: 30,
+			hariDalamBulan: 30,
+			sebagian: false,
+			postingDiketahui: true,
+			...cakupan[i]
+		})),
+		bulanKosong: [],
+		lookup: null
+	};
+}
+
+describe('ringkasanPeriode', () => {
+	it('membagi rata-rata hanya dengan bulan yang dilaporkan BE', () => {
+		const l = laporan(['2026-07', '2026-08'], [100, 300], [1000, 3000]);
+		l.bulanKosong = ['2026-05', '2026-06'];
+		const r = ringkasanPeriode(l)!;
+		expect(r.bulanBerdata).toBe(2);
+		expect(r.rataGmv).toBe(200);
+		expect(r.bulanKosong).toEqual(['2026-05', '2026-06']);
+	});
+
+	it('mempertahankan bulan nol di tengah deret sebagai bulan berdata', () => {
+		const r = ringkasanPeriode(laporan(['2026-06', '2026-07', '2026-08'], [300, 0, 300], [3000, 0, 3000]))!;
+		expect(r.bulanBerdata).toBe(3);
+		expect(r.bulanNol).toBe(1);
+		expect(r.rataGmv).toBe(200);
+		expect(r.terlemah?.bulan).toBe('2026-07');
+	});
+
+	it('menandai bulan terkuat, terlemah, dan arah bulan terakhir', () => {
+		const r = ringkasanPeriode(laporan(['2026-06', '2026-07', '2026-08'], [100, 400, 200], [1, 1, 1]))!;
+		expect(r.terbaik?.bulan).toBe('2026-07');
+		expect(r.terlemah?.bulan).toBe('2026-06');
+		expect(r.terakhir?.bulan).toBe('2026-08');
+		expect(r.pertumbuhan).toBeCloseTo(-50);
+	});
+
+	it('tidak mengarang pertumbuhan dari satu bulan atau dari pembagi nol', () => {
+		expect(ringkasanPeriode(laporan(['2026-08'], [100], [10]))!.pertumbuhan).toBeNull();
+		expect(ringkasanPeriode(laporan(['2026-08'], [100], [10]))!.terlemah).toBeNull();
+		expect(ringkasanPeriode(laporan(['2026-07', '2026-08'], [0, 100], [1, 1]))!.pertumbuhan).toBeNull();
+	});
+
+	it('meneruskan tanda bulan terakhir yang baru sebagian', () => {
+		const l = laporan(['2026-07', '2026-08'], [100, 50], [1, 1], [{}, { hariTerisi: 9, sebagian: true }]);
+		expect(ringkasanPeriode(l)!.terakhirSebagian).toBe(true);
+	});
+
+	it('menghitung GMV per 1.000 views, dan null bila views nol', () => {
+		expect(ringkasanPeriode(laporan(['2026-08'], [5000], [10_000]))!.gmvPer1kViews).toBe(500);
+		expect(ringkasanPeriode(laporan(['2026-08'], [5000], [0]))!.gmvPer1kViews).toBeNull();
+	});
+
+	it('mengembalikan null saat BE menjawab unavailable atau tanpa bulan', () => {
+		const l = laporan(['2026-08'], [100], [10]);
+		l.ada = false;
+		expect(ringkasanPeriode(l)).toBeNull();
+		expect(ringkasanPeriode(laporan([], [], []))).toBeNull();
+	});
+});
