+import type { LaporanAtribusi } from './tipe';
+
+/**
+ * Ringkasan satu periode: rata-rata per bulan, bulan terkuat dan terlemah,
+ * pertumbuhan bulan terakhir, dan GMV per 1.000 views.
+ *
+ * Dihitung dari `laporan` — jawaban `/partners/attribution` yang sama yang
+ * mengisi seluruh halaman — bukan dari permintaan kedua: `summary` dan
+ * `monthly` di jawaban itu sudah mencakup periode penuh, hanya `breakdown.rows`
+ * yang dipotong paginasi. Permintaan kedua hanya akan menggandakan angka yang
+ * sama dan bisa menjawab beda saat BE berubah di tengah.
+ *
+ * Hanya bulan yang benar-benar dilaporkan BE ikut dihitung. Bulan yang tidak
+ * ada di `coverage` tidak dianggap nol — membaginya ke dalam rata-rata akan
+ * menurunkan angka seolah bulan itu sepi, padahal datanya memang belum masuk.
+ */
+export interface TitikBulan {
+	/** 'YYYY-MM' */
+	bulan: string;
+	gmv: number;
+	views: number;
+	video: number;
+}
+
+export interface RingkasanPeriode {
+	bulan: TitikBulan[];
+	/** Bulan yang dilaporkan BE — penyebut rata-rata. */
+	bulanBerdata: number;
+	/** Bulan berdata yang GMV-nya nol: hari sungguhan tanpa penjualan. */
+	bulanNol: number;
+	rataGmv: number;
+	terbaik: TitikBulan | null;
+	terlemah: TitikBulan | null;
+	/** Bulan terakhir dibanding bulan sebelumnya, dalam persen; null bila hanya satu bulan berdata. */
+	pertumbuhan: number | null;
+	terakhir: TitikBulan | null;
+	/** Bulan terakhir belum terisi penuh, jadi pertumbuhannya masih bisa naik. */
+	terakhirSebagian: boolean;
+	/** GMV per 1.000 views; null bila tidak ada views. */
+	gmvPer1kViews: number | null;
+	/** Bulan dalam periode yang tidak dilaporkan sama sekali. */
+	bulanKosong: string[];
+}
+
+export function ringkasanPeriode(laporan: LaporanAtribusi): RingkasanPeriode | null {
+	if (!laporan.ada || !laporan.bulan.length) return null;
+
+	const bulan: TitikBulan[] = laporan.bulan.map((b, i) => {
+		let gmv = 0;
+		let views = 0;
+		let video = 0;
+		for (const s of laporan.seri) {
+			const m = s.nilai[i];
+			if (!m) continue;
+			gmv += m.gmv;
+			views += m.views;
+			video += m.video;
+		}
+		return { bulan: b, gmv, views, video };
+	});
+
+	const urutGmv = [...bulan].sort((a, b) => a.gmv - b.gmv);
+	const terakhir = bulan[bulan.length - 1];
+	const sebelum = bulan.length > 1 ? bulan[bulan.length - 2] : null;
+	const cakupanTerakhir = laporan.cakupan.find((c) => c.bulan === terakhir.bulan);
+	const views = laporan.ringkasan.views;
+
+	return {
+		bulan,
+		bulanBerdata: bulan.length,
+		bulanNol: bulan.filter((b) => b.gmv === 0).length,
+		rataGmv: laporan.ringkasan.gmv / bulan.length,
+		terbaik: urutGmv[urutGmv.length - 1],
+		terlemah: bulan.length > 1 ? urutGmv[0] : null,
+		pertumbuhan: sebelum && sebelum.gmv > 0 ? ((terakhir.gmv - sebelum.gmv) / sebelum.gmv) * 100 : null,
+		terakhir,
+		terakhirSebagian: cakupanTerakhir?.sebagian ?? false,
+		gmvPer1kViews: views > 0 ? (laporan.ringkasan.gmv / views) * 1000 : null,
+		bulanKosong: laporan.bulanKosong
+	};
+}
